(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-mx-format-codec"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-1\">一 · 事故现场：一次“听不见的溢出”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-2\">二 · 它到底在解哪个方程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-3\">三 · 适用边界：块内均匀才配得上块共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-4\">四 · 与相邻方案的边界划在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-5\">五 · 工程判断：先校准，再选格式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-6\">六 · 块共享缩放救不了谁：从一次声码器上线失真说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-7\">七 · 权重离线分块：从浮点张量到缩放因子与尾数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-8\">八 · 激活在线分块：每帧每层的即时量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-9\">九 · 张量核心块缩放矩阵乘：缩放因子随 tile 加载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-10\">十 · 块内反量化与输出回写：误差在块边界累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-11\">十一 · KV 与激活的块量化：解码阶段的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-12\">十二 · 逐层格式选择与校准：块大小与尾数位宽的联合调优</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-13\">十三 · 块边界上的失效链与实时率代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-14\">十四 · 从块内最大值到共享指数：$e_{\\max}$ 的推导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-15\">十五 · 反量化的伪代码：把公式落到内核</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-16\">十六 · 逐层选择尾数位宽：精度预算的分配推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-17\">十七 · 块边界与感受野：误差累积的推导与对齐策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-18\">十八 · 与全局缩放的差别：为什么块共享指数在音频上更稳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-19\">十九 · 请求形态与块粒度：为什么 MX 编解码器天然吃“短帧块流”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-20\">二十 · 负载不对时的第一类失败：块边界与感受野错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-21\">二十一 · 第二类失败：尾数位宽与高频段的听感耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-22\">二十二 · 第三类失败：批形态与实时率约束的冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-23\">二十三 · 负载配方的工程判断：按形态分档而非统一配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-24\">二十四 · 负载不对的边界信号：什么时候该换格式而不是调配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-25\">二十五 · 硬件档位：从 MX 原生支持反推部署形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-26\">二十六 · 并行拓扑：按层内矩阵乘切分，而不是按层切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-27\">二十七 · 量化方案：逐层选择 MXFP4 / MXFP6 / MXINT8</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-28\">二十八 · KV 策略：KV 与激活同样按块量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-29\">二十九 · 调度参数：批大小按块内元素与 tile 对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-30\">三十 · 可复现的配置思路：从负载反推，而不是从格式正推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-31\">三十一 · 边界条件：块缩放何时失效、代价落在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-32\">三十二 · 带宽账本：MX 把权重搬运压到哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-33\">三十三 · 显存与 KV：块量化的驻留成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-34\">三十四 · 通信：分离式部署下的量化收益与元数据开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-35\">三十五 · 尾延迟：块边界误差累积与实时率约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-36\">三十六 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-37\">三十七 · 逐层校准作为系统调优手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-38\">三十八 · 块缩放格式在规模上的崩点：缩放因子带宽、块边界与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-39\">三十九 · 精度失效的三种可观测形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-40\">四十 · OOM 的来源不是权重而是激活与块元数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-41\">四十一 · 批抖动与路由不均的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-42\">四十二 · 尾延迟尖刺的定位顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-43\">四十三 · 监控指标与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-44\">四十四 · 块缩放编解码器的失效链：从高频失真到尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-45\">四十五 · 同族谱系：MX 在低精度格式里的坐标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-46\">四十六 · 选型的第一判据：块内分布均匀度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-47\">四十七 · 选型的第二判据：缩放因子开销占比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-48\">四十八 · 决策表：按层型与负载形态落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-49\">四十九 · 与 NVFP4 和 FP8 的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-50\">五十 · 适用条件的硬边界与工程落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-format-codec-sec-51\">五十一 · 边界与邻族选型：MX 何时失效、与谁互换</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 514.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"432.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重按块（如 32 元素）分组，统计块内最大指数得到共享缩放因子</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"432.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">元素量化为低比特尾数（如 MXFP4/MXFP6/MXINT8），与缩放因…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"432.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时张量核心按块加载缩放因子与尾数，块内反量化后做矩阵乘</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"432.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">激活同样按块量化，声码器卷积与编解码器注意力均可用 MX 格式</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"432.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出按块反量化回 FP16/BF16，送后续层或波形合成</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-mx-format-codec-sec-1\">一 · 事故现场：一次“听不见的溢出”</h3>\n<p>某流式 TTS 服务在灰度切换声码器到 FP16 权重后，离线指标全绿：MOS 回归通过、频谱误差在阈值内、单卡吞吐翻倍。上线后投诉集中在长句尾段——齿音发毛、气声发闷，且只在超过若干秒的连续合成里出现。复现时把同一段文本切短，失真消失。根因不在声码器本身，而在上游编解码器注意力层的激活：长句推理时注意力 logits 的动态范围随上下文增长而扩张，FP16 尾数在少数通道上溢出为 inf，反量化回传时污染了相邻帧的激励，声码器把这些被污染的激励当成高频能量放大。短句不触发，是因为上下文还没长到把块内极值推出 FP16 可表示区间。</p>\n<p>这个案例的教训不是“FP16 不够好”，而是：音频模型的数值风险是<strong>块内极值驱动</strong>的，而非全局均值驱动的。全局 INT8 或通道级缩放（如 SmoothQuant 那类做法）按通道统计量定缩放，对块内突然出现的尖峰无能为力；FP16 则干脆没有缩放，只能靠指数位硬扛。工程上要的是“每 K 个元素共享一个指数”的中间态——这正是 MX（microscaling）块浮点格式要填的坑。本片段只回答两个问题：这个编解码器解决什么具体推理问题、不解决什么；机制细节与内核实现留给后续部分。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-2\">二 · 它到底在解哪个方程</h3>\n<p>把问题写成一句话：在 Blackwell 张量核心上，用低比特表示神经音频编解码器与声码器的权重与激活，同时让块内动态范围不塌缩、块间不溢出。形式化地，对每个长度 K 的块，取块内最大指数作为共享缩放因子：</p>\n<div class=\"formula\">$$x_i = s \\cdot m_i,\\quad s=2^{\\lfloor \\log_2 \\max_j |x_j| \\rfloor - e_{\\max}},\\quad m_i\\in\\text{低比特尾数}$$</div>\n<p>这里 $s$ 是块共享缩放，$m_i$ 是低比特尾数（MXFP4/MXFP6/MXINT8），$e_{\\max}$ 是尾数格式的指数上限。关键在 $s$ 由块内极值决定：块内所有元素被同一个指数“抬”到可表示区间，尾数只负责块内相对精度。这与全局 INT8 的差别是结构性的——全局缩放把整张量的极值摊给所有元素，一个尖峰就让其余元素的有效位数被压掉；块共享缩放把尖峰隔离在它所在的 32 元素块里，其余块照常保留精度。对音频模型尤其重要：声码器卷积核的权重分布在不同通道间差异极大，编解码器注意力的激活又随上下文长度漂移，两者都不服从单一全局分布。</p>\n<p>代价侧要算清楚三笔账。第一是<strong>带宽</strong>：MXFP4 相对 FP16 把权重与激活的搬运量压到四分之一，对流式 TTS 的短帧块推理是直接的显存带宽节省，因为这类负载的瓶颈常在权重流与激活回写而非算力。第二是<strong>延迟</strong>：块内反量化发生在张量核心加载路径上，缩放因子与尾数一起进 tile，反量化本身不额外起 kernel，但若块大小与 tile 不对齐，加载会退化为多次小事务，首包延迟被拉长。第三是<strong>精度预算</strong>：尾数位宽每降一档，块内量化噪声抬一档，而音频的高频段（齿音、气声）对噪声最敏感——这就是事故里“发闷”的物理来源。三笔账互相拉扯，块大小 K 与尾数位宽是唯一的两个调节旋钮。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-3\">三 · 适用边界：块内均匀才配得上块共享</h3>\n<p>MX 编解码器的适用前提是<strong>块内分布相对均匀</strong>。若一个 32 元素块里同时存在量级差三个数量级的元素，共享指数会被最大值绑架，小元素的有效尾数位被压到接近零，反量化后表现为块内“死寂”与块边界的阶跃。卷积层与注意力层的权重通常满足这个前提——同一输出通道的相邻核权重尺度相近；但激活不总是：注意力 logits 在长上下文里会出现孤立的尖峰，卷积感受野跨越帧边界时块边界与感受野不对齐，跨块反量化误差会累积成底噪抬升。因此适用边界要按层判定，而不是按模型判定。</p>\n<p>不适用或需绕开的情形有四类。<strong>其一</strong>，块过小：K 降到远小于张量核心 tile 时，缩放因子的存储与加载开销占比上升，带宽节省被元数据吃掉，且块内统计量噪声变大。<strong>其二</strong>，块过大：动态范围不足，等价于退化成粗粒度全局缩放，尖峰重新污染整块。<strong>其三</strong>，尾数过窄：MXFP4 在声码器高频段已接近听感阈值，再窄就进入可闻失真区，且失真形态是齿音毛刺而非平滑噪声，用户投诉率高。<strong>其四</strong>，内核未对齐 tile：格式转换与块缩放增加预处理与内核实现复杂度，若加载路径没按张量核心 tile 组织，实际吞吐低于预期，低精度的收益被内核开销抵消。规模上限受 Blackwell 对 MX 格式的支持粒度与内核实现复杂度约束，材料未给出具体上限，工程上应以逐层校准结果为准而非以格式标称值为准。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-4\">四 · 与相邻方案的边界划在哪</h3>\n<p>把 MX 放到量化谱系里看，它的位置由“缩放粒度”决定。全局 INT8 是整张量一个缩放，通道级缩放是一通道一个缩放，MX 是每 K 个元素一个缩放。粒度越细，动态范围保持越好，元数据开销越大。音频模型的权重分布既不是全局均匀也不是通道内均匀，而是“通道内近似均匀、通道间差异大”，所以块级粒度是匹配的：它比通道级更细，能吸收通道内的局部尖峰；又比逐元素缩放省元数据，因为缩放因子只需每 32 元素存一个指数。</p>\n<p>与 FP16 的边界更直接：FP16 不需要缩放因子，但也没有溢出保护，动态范围靠 5 位指数硬扛，一旦块内极值越界就产生 inf 并污染下游；MX 用共享指数把块内极值显式抬到安全区，代价是尾数位宽让渡给指数。所以选择不是“哪个更准”，而是“把位宽预算花在指数还是尾数上”——音频模型的高频失真对尾数敏感、对指数不敏感，这正是 MX 在声码器上比 FP16 更稳、比 INT8 更准的结构性原因。至于流式分块、渐进解码、投机解码等相邻算法，它们解决的是调度与解码顺序问题，与本条目的数值表示问题是正交的，此处不展开。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-5\">五 · 工程判断：先校准，再选格式</h3>\n<p>落地顺序应当是“逐层校准 → 选块大小与尾数 → 对齐 tile → 再谈吞吐”。逐层校准的做法：对每一层分别统计块内极值分布与高频段能量占比，声码器卷积层与编解码器注意力层分开做，因为两者的块边界与感受野对齐关系不同；对高频敏感的层保留更宽的尾数（MXFP6 或 MXINT8），对动态范围大的注意力激活优先保指数。块大小从 32 元素起步，向 tile 对齐方向调，而不是向“更细”方向调——更细的块在音频负载上收益递减，元数据与加载开销先到瓶颈。</p>\n<p>稳定性技巧要写进校准流程而非事后补丁：块边界与卷积感受野不对齐时，跨块反量化误差会累积，长句推理出现底噪抬升，因此卷积层应按感受野对齐切块，或在块边界加一次轻量重缩放；注意力层则要对 logits 的尖峰单独设保护阈值，避免单块极值绑架整块。输出侧按块反量化回 FP16/BF16 再送波形合成，保证下游合成链路不继承量化噪声。判断一个部署是否真的吃到了 MX 的收益，看两个信号：权重流带宽是否真的下降（而非被元数据抵消），以及长句尾段的高频失真是否消失（而非被离线指标掩盖）。事故里的“短句正常、长句发闷”正是后者失效的典型形态——它提醒我们，音频推理的数值问题从来不在平均值上，而在块内极值上。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-6\">六 · 块共享缩放救不了谁：从一次声码器上线失真说起</h3>\n<p>某流式 TTS 服务在 Blackwell 上把声码器权重从 FP16 直接换成全局 INT8，离线指标看不出问题，上线后长句合成却出现齿音发闷、气声被抹平的投诉。根因不在量化本身，而在权重分布：声码器卷积核与编解码器注意力投影的权重动态范围极大，少数大幅值通道主导了全局缩放因子，其余通道被压进极窄的量化格点，高频细节首先被牺牲。换回 FP16 又撞上另一堵墙——部分层的激活与权重在上采样与残差叠加处逼近 FP16 上限，溢出后波形直接崩坏。这正是微缩放格式要处理的推理问题：在保持低比特带宽收益的同时，让每个局部块自己决定动态范围。块共享缩放的写法是</p>\n<div class=\"formula\">$$x_i = s \\cdot m_i,\\quad s = 2^{e_{\\max}},\\quad m_i \\in \\text{低比特尾数}$$</div>\n<p>其中 $e_{\\max}$ 是块内最大指数，$s$ 由它单独决定，$m_i$ 只承担块内相对形状。以 32 元素为一块、尾数取 MXFP4/MXFP6/MXINT8，缩放因子开销约为每 32 个值一个指数，块内动态范围由尾数位宽封顶。它解决的是“全局缩放被离群值绑架”和“FP16 溢出”这两类问题；它不解决块内本身就不均匀的分布——若一块里同时存在接近零的系数和一个大幅值系数，低比特尾数仍然只能保住后者，前者落入同一格点。它也不解决内核实现问题：格式转换、块缩放查表、反量化若未与张量核心 tile 对齐，理论带宽收益会被实际吞吐吃掉。</p>\n<p>边界因此可以写得很具体。适合的是块内相对均匀的卷积与注意力层，块大小 $K$ 是动态范围与缩放开销的折中：$K$ 过小，每块一个指数的存储与加载开销上升，反量化指令密度变高；$K$ 过大，块内极值重新主导缩放，退化成准全局量化。失效条件有三类。其一，块大小与尾数位宽未逐层调优，声码器高频段出现明显失真，听感上就是齿音与气声发闷——这是尾数位宽不足的直接代价，不是校准能补的。其二，激活按块量化时块边界与卷积感受野不对齐，跨块反量化误差沿层累积，长句推理底噪抬升，表现为段落尾部噪声 floor 上浮。其三，内核未对齐张量核心 tile，实际吞吐低于预期，此时低精度只省了显存没省时间。</p>\n<p>系统代价要按数据流算清楚。权重侧：每 32 元素附带一个缩放指数，相对纯 INT8 的存储增量很小，但预处理阶段要做分块、求块内最大指数、量化尾数、重排布局，这是一次性离线成本；激活侧则是每帧在线做同样的事，流式 TTS 的短帧块使这笔开销按帧重复，直接压在首包延迟上。带宽收益来自尾数位宽：MXFP4 相对 FP16 把权重与激活的搬运量压到四分之一量级，对受显存带宽约束的解码阶段是实打实的；但块缩放因子的加载是额外的、非规则的访问，若布局不连续会破坏合并访问。算力上，Blackwell 张量核心原生支持 MX 格式，块内反量化在 MMA 流水内完成，这才是它相对“先反量化再走 FP16 矩阵乘”的优势所在；一旦落到不支持的路径上，反量化就变成独立的逐元素内核，吞吐立刻回落。工程判断很直接：先确认目标层的权重分布是否块内均匀、感受野是否与块边界可对齐，再决定 $K$ 与尾数位宽；对声码器高频敏感层宁可保留 MXFP6 或 FP16，把 MXFP4 留给对失真不敏感的投影层，而不是全模型一刀切。</p>\n<h3 id=\"alg-mx-format-codec-sec-7\">七 · 权重离线分块：从浮点张量到缩放因子与尾数</h3>\n<p>按数据流动的顺序拆解 MX 编解码器推理，第一步发生在模型加载之前的离线阶段，对象是声码器卷积核与编解码器注意力投影矩阵的权重张量。对每个权重张量，沿输入通道维（即矩阵乘的 K 维）以 32 元素为一块切分，块内统计最大绝对值的指数，得到该块唯一的共享缩放因子。这一步的输入是 FP16/BF16 权重，输出是两份并行的数据：每 32 个元素一个的缩放因子数组，以及同形状的低比特尾数数组。缩放因子的取法决定了整个格式的动态范围上限：</p>\n<div class=\"formula\">$$s=2^{\\lfloor \\log_2 \\max_j |x_j| \\rfloor - e_{\\max}},\\quad m_i=\\mathrm{quant}\\!\\left(\\frac{x_i}{s}\\right)$$</div>\n<p>这里 $e_{\\max}$ 是尾数格式可表示的最大指数（MXFP4 的尾数为 E2M1，指数域极窄），减去它意味着把块内最大值顶到尾数能表示的最大量级，块内其余元素按比例落入尾数格点。与全局 INT8 的通道级缩放相比，块共享指数的关键差别在于缩放因子随块走：音频权重中相邻 32 个通道的能量常常跨越数个数量级，全局缩放只能迁就最大通道，小块缩放则让每个块各自贴住自己的量级。代价在离线侧：每个张量多出一份 $K/32$ 比例的缩放因子存储，权重文件体积约为纯 MXFP4 尾数的 1.06 倍（4 bit 尾数加 8 bit 缩放摊到 32 元素）；同时量化本身是一次全张量扫描，编译期一次性成本，不进入推理热路径。工程上这一步通常与权重格式转换合并进 TensorRT-LLM 的 checkpoint 转换或 vLLM 的量化加载流程，产物直接落成张量核心可消费的块布局，避免运行时再做重排。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-8\">八 · 激活在线分块：每帧每层的即时量化</h3>\n<p>推理开始后，第一个在线步骤是对进入矩阵乘的激活做同样的块量化。以流式 TTS 的短帧块为例：编解码器解码器每收到一帧隐变量，先经输入投影，该投影的激活张量形状为 [批, 帧内 token, 隐藏维]，沿隐藏维以 32 元素分块，块内求最大指数、生成缩放因子、把激活压成低比特尾数。输入是 BF16 激活，输出是激活尾数加激活缩放因子，二者与权重侧的两份数据在张量核心处汇合。这一步的系统代价是纯带宽与延迟：激活量化发生在每个矩阵乘之前，属于逐层、逐帧的重复工作，其开销与激活元素数成正比，而激活元素数又正比于批大小与帧内 token 数。对首包延迟敏感的流式场景，激活量化内核必须与前一层的输出融合，否则每层多一次读写往返，在 NVL72 这种高带宽但延迟敏感的拓扑上会把首包推迟。具体例子：声码器上采样前的卷积层通道数大、帧长短，激活量化的固定开销占比高，工程上倾向把该层留在 BF16 或改用 MXFP6，把 MXFP4 留给通道数更大、算术强度更高的中段卷积。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-9\">九 · 张量核心块缩放矩阵乘：缩放因子随 tile 加载</h3>\n<p>第三步是 MX 格式真正兑现吞吐的地方。Blackwell 张量核心原生支持块缩放矩阵乘，其数据通路不是先把整块反量化成 FP16 再乘，而是在 MMA 指令内部按块取缩放因子、对尾数做块内反量化后累加。输入是权重尾数、权重缩放因子、激活尾数、激活缩放因子四份数据，输出是 FP32 累加结果。内核按 tile 加载，tile 的 K 维必须与 32 元素块边界对齐，否则一个 tile 会跨块取到两个不同的缩放因子，内核要么退化成标量路径，要么插入额外的块边界处理。这正是失败模式里“内核未对齐张量核心 tile 则实际吞吐低于预期”的来源。代价结构上，块缩放矩阵乘的算术吞吐由尾数位宽决定：MXFP4 相对 BF16 把每次 MMA 的乘数位宽压到四分之一，权重带宽同步下降，但缩放因子的加载与块内反量化逻辑占用了额外的指令槽与寄存器，实际吞吐增益小于位宽比例。对编解码器注意力，QK^T 与 PV 两个矩阵乘都可走 MX 路径，但注意力分数对尾数误差更敏感，工程判断是把 QK^T 留在 MXFP6 或 BF16、只对 PV 与投影走 MXFP4，用混合精度换取长句下的稳定性。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-10\">十 · 块内反量化与输出回写：误差在块边界累积</h3>\n<p>矩阵乘输出仍是 FP32 累加值，第四步把它按块反量化回 FP16/BF16 送后续层或波形合成。反量化的输入是累加器中的块结果与对应缩放因子，输出是 BF16 张量。这一步看似只是乘一个标量，真正的工程风险在块边界：声码器卷积的感受野跨越多个输入块，若激活按 32 元素分块而卷积核在通道维上的跨度不与块边界对齐，相邻块各自反量化产生的微小偏差会在卷积求和时叠加，长句推理表现为底噪抬升。缓解手段是让卷积层的块划分沿通道维与卷积核的输入通道分组对齐，或在卷积前保留一份块缩放因子的连续视图供跨块校正。系统代价上，反量化是逐元素的乘加，带宽上等价于把 FP32 累加器写回 BF16，在声码器高采样率输出的最后一层，这一步的输出元素数正比于波形采样点，是整条链路上显存写带宽的主要消耗点之一。具体例子：48 kHz 声码器一次合成 20 ms 帧即 960 个采样点、多通道并行，最后一层反量化的写带宽远高于中间层，因此该层通常不做 MX 量化而直接 BF16 输出。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-11\">十一 · KV 与激活的块量化：解码阶段的带宽账</h3>\n<p>自回归解码阶段，KV cache 是显存与带宽的主项，MX 格式在这里的角色与权重不同：KV 是按 token 逐个写入、按块读出。写入时每个新 token 的 K/V 向量沿头维以 32 元素分块量化后追加进 cache，读出时注意力内核按块加载缩放因子与尾数，块内反量化后参与 QK^T。输入是新生成的 BF16 K/V，输出是 cache 中的尾数加缩放因子。代价账很清楚：KV 尾数位宽从 16 bit 降到 4 bit 意味着同样显存容纳四倍 token 数，或在同样 token 数下把每步注意力的 KV 读带宽压到四分之一，这对长上下文流式对话的解码吞吐是直接收益。但 KV 的块划分沿头维，而注意力的头数与头维在不同层不同，块边界与头边界不对齐时，一个头会跨两个缩放因子，反量化误差在 softmax 前被放大。工程判断是头维能被 32 整除的层直接用 MXFP4 KV，不能整除的层补零到块边界或退回 MXFP6，避免为省显存引入注意力分数抖动。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-12\">十二 · 逐层格式选择与校准：块大小与尾数位宽的联合调优</h3>\n<p>最后一步不是运行时的数据流步骤，而是贯穿上述四步的配置决策：逐层选择块大小与尾数位宽，并对声码器卷积与编解码器注意力分别校准块缩放。输入是每层的权重分布统计与激活分布统计，输出是一张逐层格式表，供离线转换与在线内核共同消费。块大小 $K$ 的折中写在公式里：$K$ 越小，块内动态范围越窄、缩放因子开销越大（每 $K$ 个元素 8 bit）；$K$ 越大，块内最大值越可能远离多数元素，尾数格点被浪费。32 元素是张量核心 tile 与缩放开销的平衡点，但并非每层最优。尾数位宽的折中更直接：MXFP4 的 E2M1 只有 16 个可表示值，对声码器高频段（齿音、气声所在的 4–8 kHz 以上）的细微谱包络刻画不足，过小尾数直接表现为齿音发闷、气声失去质感；MXFP6 多两位尾数，高频失真显著缓解但带宽翻倍。校准的具体做法是对每层跑一遍代表性音频帧，比较 MX 量化前后该层输出的谱误差，把误差超阈值的层升档。系统代价是校准本身需要一次前向扫描与谱分析，属于一次性工程投入；运行时代价则体现在格式表不一致导致的混合精度内核切换，同一算子在不同层走不同 MX 路径会增加内核调度与编译实例数，这是 MX 格式转换与块缩放带来的内核实现复杂度在部署侧的具体体现。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-13\">十三 · 块边界上的失效链与实时率代价</h3>\n<p>MX 编解码器推理真正的风险不在格式本身，而在“块”与“数据流”不对齐的三处接缝。第一处是激活量化的块边界与声码器卷积感受野的错位：卷积核在时域上跨越多个量化块，块内反量化在边界处产生不连续的量化台阶，误差随层数累积，长句合成时表现为底噪抬升而非单帧失真。第二处是编解码器注意力的 KV 按块量化后，跨块反量化误差在注意力加权中被放大——softmax 权重对键值的小扰动敏感，块边界处的尾数截断会改变注意力分布，进而影响基频与音色的稳定性。第三处是缩放因子本身的存储开销：块大小 K=32 时，每个块附带一个指数，若尾数为 MXFP4，则有效位宽为 4+8/32=4.25 bit；K 缩小到 16 则升至 4.5 bit，K 放大到 64 则降至 4.125 bit 但块内动态范围被压缩。这一权衡可用有效位宽公式直接衡量：</p>\n<div class=\"formula\">$$b_{\\text{eff}} = b_m + \\frac{b_s}{K},\\quad \\text{块内可表示范围} \\approx 2^{b_m}\\cdot 2^{e_{\\max}-e_{\\min}}$$</div>\n<p>其中 $b_m$ 为尾数位宽、$b_s$ 为缩放因子位宽、K 为块元素数。工程判断是：声码器卷积层宜用较小 K 保住块内动态范围，注意力层宜用较大 K 摊薄缩放开销，逐层选择而非全局统一。失效条件很具体——若内核未按张量核心 tile 对齐加载缩放因子与尾数，块缩放会退化为逐元素反量化，实际吞吐低于预期；若尾数位宽压到 MXFP4 以下而该层权重块内分布本身离散，高频段齿音与气声发闷的听感失真不可通过后处理挽回。</p>\n<p>系统代价必须按流式 TTS 的实时率约束来算。首包延迟由预填充阶段决定，MX 格式的权重解包与块反量化在预填充时是一次性开销，但解码阶段每帧都要重做激活量化与块反量化，这部分是稳态成本。设单帧解码需处理 $N$ 个量化块、每块反量化耗时为 $t_q$，则每帧新增的量化开销约为 $N\\cdot t_q$，它与张量核心矩阵乘时间在同一量级时才会威胁实时率——这正是内核实现复杂度成为规模上限的原因。显存侧的收益是直接的：MXFP4 相对 FP16 把权重带宽压到约四分之一，KV 按块量化同样降低解码阶段的键值读取带宽，对长上下文流式合成尤为关键。但收益被块缩放因子的元数据访问模式侵蚀：缩放因子若与尾数分离存储，解码时需两次访存，L2 命中率下降会抵消部分带宽节省。</p>\n<table class=\"mini\"><thead><tr><th>接缝位置</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>卷积块边界</td><td>跨块反量化台阶累积，底噪抬升</td><td>长句实时率下降，需逐层校准</td></tr><tr><td>注意力 KV 块量化</td><td>注意力分布扰动，音色不稳</td><td>解码阶段额外反量化访存</td></tr><tr><td>缩放因子元数据</td><td>两次访存，L2 命中下降</td><td>带宽节省被部分抵消</td></tr></tbody></table>\n<p>因此该方案的适用边界应表述为：块内权重分布相对均匀的卷积与注意力层可放心用 MX，块内分布离散或对相位敏感的上采样层应保留更高尾数位宽或退回 FP16；块大小与尾数位宽必须逐层调优并对声码器卷积与编解码器注意力分别校准，否则块边界误差累积会在长句推理中暴露为可听的底噪。规模上限不由格式决定，而由张量核心 MX 支持粒度与内核 tile 对齐质量决定——这是部署前必须用逐层校准脚本验证的工程项，而非格式选型问题。</p>\n<h3 id=\"alg-mx-format-codec-sec-14\">十四 · 从块内最大值到共享指数：$e_{\\max}$ 的推导链</h3>\n<p>核心公式里的 $s=2^{\\lfloor \\log_2 \\max_j |x_j| \\rfloor - e_{\\max}}$ 不是拍脑袋写出来的，它是一条从“块内极值”到“可表示范围”的推导链。设块内元素为 $x_1,\\dots,x_K$，先取绝对最大值 $M=\\max_j|x_j|$。低比特尾数格式（以 MXFP4 的 E2M1 为例）有一个固定的最大可表示尾数 $m_{\\max}$，其量级由指数位宽决定。要让块内最大值恰好落在尾数可表示的上界而不溢出，缩放因子必须满足 $s\\cdot m_{\\max}\\ge M$，且 $s$ 取 2 的整数幂以便硬件用移位实现。于是取 $s=2^{\\lfloor\\log_2 M\\rfloor-e_{\\max}}$，其中 $e_{\\max}$ 是尾数格式隐含的最大指数偏置。关键一步在于：$\\lfloor\\log_2 M\\rfloor$ 把连续的 $M$ 离散到最近的 2 的幂次，这一步牺牲了不到一倍的动态范围，换来缩放因子只含指数、不含尾数——硬件只需对指数做整数加减，反量化时把尾数左移相应位即可，无需浮点乘法。这正是 MX 能在张量核心上以接近整型吞吐运行的根本原因。</p>\n<p>逐项看：$x_i$ 是原始权重或激活；$m_i$ 是量化后的低比特尾数，MXFP4 为 1 符号位 + 2 指数位 + 1 尾数位，MXFP6 为 E3M2，MXINT8 为对称 8 位整型；$s$ 是块共享缩放，每 $K$ 个元素只存一个。$K=32$ 是事实给定的典型块大小，它决定了缩放开销比：每 32 个元素附带一个 8 位指数，额外存储开销约 3%。块越小，块内分布越均匀、动态范围保留越好，但缩放因子本身的带宽与解码指令占比上升；块越大，缩放开销摊薄，但块内极值可能远离多数元素，导致小值元素被压到尾数下界而丢失。这个折中在声码器上尤其敏感：卷积核权重在同一输出通道内往往量级相近，32 元素块刚好覆盖一个通道切片，是分布均匀性与开销的平衡点。</p>\n<div class=\"formula\">$$x_i = s \\cdot m_i,\\quad s=2^{\\lfloor \\log_2 \\max_j |x_j| \\rfloor - e_{\\max}},\\quad m_i\\in\\text{低比特尾数}$$</div>\n<p>代价落在三个地方。其一，量化误差上界为半个尾数最小间隔乘以 $s$，即 $\\Delta/2\\cdot s$，尾数位宽每少一位，块内信噪比下降约 6 dB，对声码器高频段（齿音、气声所在的 4–8 kHz 以上）直接表现为发闷。其二，每个块多一次指数提取与移位，反量化内核的指令数随块数线性增长，若块数与张量核心 tile 不对齐，这部分开销会吃掉低精度带来的吞吐收益。其三，激活按块量化时，块边界若与卷积感受野错位，跨块误差会在层间累积，长句推理出现底噪抬升——这是 MX 在音频链路上区别于纯权重压缩的独有风险。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-15\">十五 · 反量化的伪代码：把公式落到内核</h3>\n<p>公式要变成可实现的推理路径，必须明确“何时反量化”。MX 的设计取向是块内反量化后立即进入矩阵乘，而不是先把整张量还原成 FP16 再算——后者会让带宽优势归零。下面给出权重侧与激活侧统一的块解码伪代码思路，用文字描述控制流：对每个 $K$ 元素块，从打包存储中取出 8 位共享指数 $e$，用查表或移位构造 $s=2^{e}$；随后对块内每个尾数 $m_i$ 做符号扩展与左移，得到定点中间值；最后与 $s$ 相乘（或直接把移位结果送入 MMA 的输入寄存器）。关键在于把“乘 $s$”折叠进张量核心的累加前处理，使每个元素只付一次移位代价。</p>\n<ul>\n<li>步骤 1：按 tile 对齐加载。权重按 $K=32$ 打包，加载粒度必须与 Blackwell 张量核心的 MMA tile 边界对齐，否则内核会退化为逐块标量解码。</li>\n<li>步骤 2：指数广播。一个块的 $s$ 只解码一次，广播到该块覆盖的所有尾数通道，避免每元素重复取指数。</li>\n<li>步骤 3：尾数展开。MXFP4 的 4 位尾数按 E2M1 语义展开为定点数，MXINT8 直接符号扩展；两者共用同一套移位通路。</li>\n<li>步骤 4：块内反量化并送入 MMA。反量化结果不落回全局显存，停留在寄存器或 TMEM 中供矩阵乘消费。</li>\n<li>步骤 5：输出侧再量化。矩阵乘累加结果按输出块统计新的 $s'$，量化回低比特尾数送下一层，或反量化回 FP16/BF16 送波形合成。</li>\n</ul>\n<p>这套伪代码的系统代价集中在步骤 1 与步骤 4。步骤 1 的对齐要求意味着内核实现复杂度上升：块大小 32 与 tile 形状不整除时，需要填充或跨块拼接，实际吞吐低于理论值。步骤 4 的“不落显存”要求寄存器压力可控，块内并行度不足时反量化会成为 MMA 前的串行瓶颈。以一个流式 TTS 的声码器卷积层为例：若该层输出通道数为 512、卷积核宽 3，按 32 元素分块则每通道切片恰好一块，缩放因子随权重常驻，解码开销被摊到整个推理生命周期；但若通道数不是 32 的整数倍，尾部块需要单独处理，内核分支增加，首包延迟的抖动随之变大。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-16\">十六 · 逐层选择尾数位宽：精度预算的分配推导</h3>\n<p>MXFP4、MXFP6、MXINT8 不是三选一的全局开关，而是逐层分配的精度预算。推导的出发点是：每层的量化误差对最终波形失真的贡献不同。编解码器注意力层的权重分布跨头差异大，块内极值可能由少数离群通道主导，尾数位宽不足时这些通道被截断，注意力分数偏移会放大到帧级特征；声码器卷积层权重块内相对均匀，MXFP4 即可，但高频重建对尾数分辨率敏感，过小尾数直接损伤齿音。于是分配规则可以写成：给定层 $l$ 的块内动态范围比 $R_l=\\max_j|x_j|/\\min_{j,|x_j|&gt;0}|x_j|$，当 $R_l$ 超过尾数格式可覆盖的指数跨度时，升一档位宽；否则维持低比特。这是一个定性判据，材料未给出具体阈值，工程上以校准集上的波形失真与实时率为联合约束逐层试。</p>\n<table class=\"mini\"><thead><tr><th>层类型</th><th>分布特征</th><th>位宽取向</th><th>主要代价</th></tr></thead><tbody><tr><td>编解码器注意力</td><td>跨头差异大、存在离群通道</td><td>MXFP6 或 MXINT8</td><td>带宽上升，注意力分数偏移风险下降</td></tr><tr><td>声码器卷积</td><td>块内较均匀</td><td>MXFP4</td><td>高频段尾数分辨率不足时齿音发闷</td></tr><tr><td>激活（逐块）</td><td>随帧内容波动</td><td>与权重同档或高一档</td><td>块边界误差累积，长句底噪抬升</td></tr></tbody></table>\n<p>代价的量化方式：位宽从 MXFP4 升到 MXFP6，权重带宽增加 50%，张量核心吞吐按位宽比例下降；从 MXFP6 升到 MXINT8 再增约 33%。因此逐层选择本质是在“音质预算”与“带宽/吞吐预算”之间做线性规划，约束是首包延迟与实时率。具体例子：同一编解码器模型，若把全部卷积层压到 MXFP4 而注意力保留 MXFP6，权重带宽相比全 FP16 显著下降，声码器卷积的 MMA 吞吐提升，但需对卷积层单独校准块缩放，否则块边界处量化误差累积会在长句尾部表现为底噪抬升。校准的动作是：用代表性音频片段跑一遍，统计每层输出与 FP16 参考的偏差，把偏差超限的层升档，其余保持低比特——这一步是离线预处理，不进入推理热路径，但增加了格式转换的工程复杂度。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-17\">十七 · 块边界与感受野：误差累积的推导与对齐策略</h3>\n<p>激活按块量化时，误差不是独立同分布的：相邻块的缩放因子不同，反量化后在块边界产生阶跃，这个阶跃经过卷积感受野被平滑但不被消除。推导的关键一步是把块边界误差建模为分段常数的扰动 $\\epsilon(x)$，其幅度正比于相邻块 $s$ 的相对差与尾数截断误差之和。当卷积核宽大于块内元素跨度时，一个输出点会同时看到多个块的扰动，误差按核权重加权叠加；层数越深，叠加次数越多，最终表现为可听的底噪。缓解策略有两条：一是让块边界与卷积感受野对齐，即按通道或按核切片分块，使一个感受野内的元素尽量落在同一块；二是对声码器卷积与编解码器注意力分别校准块缩放，注意力侧按头分块、卷积侧按通道分块，避免用一套全局块划分硬套两种分布。</p>\n<p>系统代价在这里体现为内核实现的灵活性成本。按通道分块意味着块大小不再是固定的 32，而是随通道数变化，缩放因子的存储布局与加载粒度都要相应调整；若强行固定 32 而通道数不整除，尾部块要么填充（浪费带宽）要么跨通道拼接（引入跨分布误差）。对齐策略还会影响批调度：流式 TTS 的短帧块按块内元素与张量核心 tile 对齐批大小，块划分一变，批的可行形状随之变化，连续批处理的填充率下降。工程判断是：优先保证块划分与感受野对齐，再在剩余自由度里调批形状；反过来先凑批再改块划分，会把误差累积问题推到听感上，且难以在后期用调度弥补。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-18\">十八 · 与全局缩放的差别：为什么块共享指数在音频上更稳</h3>\n<p>把 MX 与全局 INT8 的通道级缩放对比，差别不在“量化”这个动作，而在缩放因子的自由度。全局或通道级缩放只允许每通道一个 $s$，当通道内存在少数大幅值权重时，$s$ 被极值拉高，其余小权重被压到整型下界附近，有效位数骤减；音频模型的权重分布恰恰是这种“少数通道主导、多数通道细小”的形态，全局缩放会在细小通道上损失明显。MX 的块共享指数把 $s$ 的自由度提高到每 32 元素一个，块内极值只影响本块，细小元素在相邻块里获得更合适的 $s$，从而保留块内动态范围。相比 FP16，MX 不需要溢出保护：FP16 的指数位宽有限，声码器某些层的权重动态范围会触及上界，需要缩放或裁剪；MX 的共享指数按块自适应，溢出风险被局部化。</p>\n<p>代价是缩放因子本身的存储与解码开销，以及逐层调优的工程量。块越小，缩放因子越多，预处理阶段的格式转换越复杂；块越大，越接近全局缩放的行为，动态范围优势减弱。适用边界因此明确：适合权重分布块内相对均匀的卷积与注意力层；块过小则缩放开销上升，块过大则动态范围不足。规模上限受张量核心 MX 格式支持与内核实现复杂度约束，材料未给出具体上限，工程上以“内核是否对齐 tile、预处理是否可离线完成”作为可行性判据。一个具体判断：若某层的块内动态范围比已经小到尾数格式可轻松覆盖，继续减小块大小只增加开销而不改善音质，此时应把块大小调大或直接降位宽，把预算让给真正需要精度的层。</p>\n<h3 id=\"alg-mx-format-codec-sec-19\">十九 · 请求形态与块粒度：为什么 MX 编解码器天然吃“短帧块流”</h3>\n<p>MX 格式的负载适配性，首先由它的数据布局决定：每 32 个元素共享一个缩放指数。这意味着一次矩阵乘的最小有意义工作单元不是单个 token，也不是整条句子，而是“块对齐的张量切片”。神经音频编解码器与声码器的推理请求恰好天然是短帧块流——编码器把波形切成帧，声码器把帧还原成波形，帧长与块大小在同一量级上，因此请求形态与格式粒度是对齐的。反过来说，任何把 MX 编解码器塞进“长序列、单请求、低并发”形态的做法，都会让块缩放的开销摊不薄。</p>\n<p>负载配方的第一维是请求形态。流式 TTS 的请求是持续到达的短帧块，每个块携带自己的激活量化参数；编解码器推理的请求是定长或变长的帧组，帧与帧之间在时间上连续但在批维度上独立。这两类形态的共同点是：单请求的计算量小、请求到达频繁、对首包延迟敏感。MX 的块共享缩放在这种形态下是正收益，因为缩放因子的读取可以与尾数读取合并成一次块加载，张量核心按 tile 消费，块内反量化不引入额外同步。</p>\n<p>第二维是长度分布。MX 编解码器的性能对帧长分布敏感，但不是线性的：帧长过短，块内元素填不满张量核心 tile，缩放因子的固定开销占比上升；帧长过长，单块跨越多个语义单元，块内动态范围被拉大，低比特尾数的相对误差上升。工程判断是让帧长落在“块大小整数倍附近、且不超过一个张量核心 tile 的 K 维”这个区间内，使块边界与 tile 边界重合。材料未给出具体帧长数值，但 32 元素块这一锚点已经限定了合理帧长的下界。</p>\n<p>第三维是并发与批大小。MX 格式的批处理有一个隐性约束：同一批内不同请求的激活缩放因子不能共享，否则跨请求的块边界会错位。因此批大小应按“块内元素数与张量核心 tile 对齐”来组织，而不是按请求数凑整。代价体现在显存带宽上：每个请求每层都要携带自己的块缩放因子，批越大，缩放因子的总字节数线性上升，虽然相对尾数主体仍是小头，但在 L2 命中率下降时会变成可见的带宽开销。</p>\n<div class=\"formula\">$$\\text{有效吞吐} \\approx \\frac{B \\cdot K \\cdot b_m}{B \\cdot (K \\cdot b_m + b_s) + \\text{tile 填充浪费}}$$</div>\n<p>其中 $B$ 为批内块数，$K$ 为块大小，$b_m$ 为尾数位宽，$b_s$ 为缩放因子位宽。这个式子说明：批大小并非越大越好，tile 填充浪费随批内块数的不整齐而放大。具体例子：一个流式 TTS 请求按帧到达，若调度器把 3 个不足 32 元素的尾帧拼进同一批，就会产生三次半块反量化，缩放因子读取次数不变但有效元素数下降，实时率约束下这部分浪费直接转化为首包延迟。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-20\">二十 · 负载不对时的第一类失败：块边界与感受野错位</h3>\n<p>声码器卷积是 MX 编解码器最脆弱的负载点。卷积的感受野跨越多个时间步，而 MX 的块边界是按元素线性切分的；当块边界与卷积感受野不对齐时，同一个感受野内的元素被分到不同块、携带不同缩放因子，反量化后拼接会产生跨块的数值不连续。材料给出的失败模式是明确的：激活按块量化时块边界与卷积感受野不对齐，导致跨块反量化误差累积，长句推理出现底噪抬升。</p>\n<p>这个失败的机制值得拆开看。卷积核在时间维上滑动，每个输出位置聚合一段输入；如果这段输入的量化误差在块边界处发生跳变，误差不会随卷积平均掉，反而因为卷积核的正负权重混合而被放大成低频纹波。长句推理中这种纹波沿时间累积，表现为底噪随句长上升。工程上的对策不是缩小块，而是让卷积的输入布局按感受野对齐分块——即把块边界放在卷积核步长的整数倍上，使每个感受野完整落在块内或按固定模式跨块。</p>\n<p>代价体现在内核实现复杂度上：对齐分块要求卷积内核知道块布局，不能直接复用通用卷积实现。若内核未对齐张量核心 tile，实际吞吐低于预期——这是材料列出的第二条失败模式。这里的因果关系是：对齐分块改变了数据布局，布局变化若未反映到 tile 映射上，张量核心的加载模式就从连续块加载退化为跨步加载，带宽利用率下降。</p>\n<p>具体例子：一个声码器上层卷积的核宽跨越多个 32 元素块，若按默认线性分块，每个输出位置要读取 2 到 3 个块的缩放因子并做三次反量化再拼接；若按感受野对齐分块，每个输出位置只读一个缩放因子，反量化次数减半，但需要额外的布局重排步骤。重排的代价是一次性预处理，收益是每帧推理的稳定吞吐，这个交换在流式形态下是划算的，在离线批量形态下则要重新评估。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-21\">二十一 · 第二类失败：尾数位宽与高频段的听感耦合</h3>\n<p>MXFP4 与 MXFP6 的选择不是精度指标问题，而是听感问题。音频信号的能量集中在低频，高频段（齿音、气声、瞬态）能量低但感知敏感；低比特尾数在高频段的量化台阶相对于信号幅度更大，误差被听觉系统放大。材料给出的失败模式是：块大小与尾数位宽未逐层调优时，声码器高频段出现明显失真，听感表现为齿音与气声发闷。</p>\n<p>机制上，这来自块共享缩放的一个结构性偏差：缩放因子由块内最大指数决定，块内小幅值元素被压到尾数的最低位附近，有效位数不足。声码器的高频段恰恰是“块内小幅值元素密集”的区域，MXFP4 的四位尾数在这种分布下只剩两三位有效精度。逐层调优的含义是：对高频重建关键的层用 MXFP6 或 MXINT8，对动态范围大但感知不敏感的层用 MXFP4，而不是全局统一位宽。</p>\n<p>代价是显存与带宽的非均匀分布：逐层位宽意味着权重存储不再是单一格式，块缩放因子的位宽也可能随层变化，加载路径需要按层分派。这在显存带宽上是混合收益——关键层位宽上升增加带宽，非关键层位宽下降节省带宽，净效果取决于层的比例。工程判断是先按感知重要性分层，再按层做位宽搜索，而不是按参数数量平均分配。</p>\n<p>具体例子：编解码器注意力层的权重分布相对均匀，MXFP4 的块内动态范围足够；声码器上采样卷积的权重分布尾部厚，块内最大指数被少数大权重拉高，小幅值权重被压到低位，这一层就应升到 MXFP6。材料未给出具体层数与位宽组合，但“逐层调优”这一要求本身已经说明统一位宽不是可用配方。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-22\">二十二 · 第三类失败：批形态与实时率约束的冲突</h3>\n<p>流式 TTS 的 SLO 以首包延迟与实时率为约束，这两个约束对批大小的要求方向相反。首包延迟要求小批、快返回；实时率要求大批、高吞吐。MX 编解码器的块缩放开销让这个矛盾更尖锐：小批时缩放因子读取的固定开销占比高，大批时块边界错位与填充浪费上升。负载配方的核心就是在这个矛盾里找可行点。</p>\n<p>机制上，可行点由块对齐条件决定：批内块数应是张量核心 tile 的整数倍，且每块的元素数填满 tile 的 K 维。满足这个条件时，缩放因子读取与尾数读取合并为一次块加载，反量化在寄存器内完成，不产生额外同步。不满足时，内核要么做 padding（浪费算力），要么做拆分（增加同步）。材料未给出具体批大小与 SLO 数值，但给出了对齐原则，这已经足以排除“按请求数凑批”的做法。</p>\n<p>代价体现在延迟抖动上：块对齐的批在稳态下延迟平稳，但在请求到达不均匀时，调度器为了凑齐 tile 整数倍会引入等待，等待时间直接加到首包延迟上。工程上的缓解是把流式请求按帧而非按句聚合，帧到达即触发块对齐检查，凑不齐就发半块批并接受填充浪费，而不是无限等待。这是一个显式的延迟换吞吐的取舍，需要在 SLO 里写明。</p>\n<p>具体例子：三个流式 TTS 请求同时到达，每个请求的首帧都是 32 元素块，批内共 3 块；若张量核心 tile 的 K 维是 4 块，则第 4 块为空，内核做一次填充反量化。填充块的缩放因子仍需读取，但尾数为零，这部分带宽是纯开销。若调度器等待第四个请求到达再发批，首包延迟增加一个请求间隔；若不等待，实时率略降但首包延迟守住。负载配方要回答的就是这个等待阈值。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-23\">二十三 · 负载配方的工程判断：按形态分档而非统一配置</h3>\n<p>把上述三类失败放在一起，负载配方的结论是按请求形态分档，而不是给 MX 编解码器一套统一配置。流式短帧块形态优先保首包延迟，批大小按 tile 对齐、允许半块填充；离线批量形态优先保吞吐，批大小按块数整数倍凑齐、接受等待；长句连续推理形态优先保稳定性，块边界按感受野对齐、关键层升位宽。三档的块大小与尾数位宽组合不同，缩放因子的存储布局也不同。</p>\n<p>分档的代价是内核分派复杂度：同一模型在不同形态下走不同内核路径，路径切换点需要按请求类型而非按批大小触发，否则同一批内混合形态会导致布局冲突。材料提到的“MX 格式转换与块缩放增加预处理与内核实现复杂度”在这里具体化为分派逻辑的维护成本。工程判断是把分档收敛到两到三档，用请求元数据里的形态标签做路由，而不是让调度器在线推断。</p>\n<p>稳定性技巧上，材料要求对声码器卷积与编解码器注意力分别校准块缩放，避免块边界处量化误差累积。这条要求的负载含义是：两类层的校准数据要来自各自形态下的真实输入分布，不能用同一批校准样本。流式形态的激活分布与离线形态不同，用离线校准的缩放因子跑流式请求，块内最大指数的估计会偏高，小幅值元素的有效精度进一步下降。</p>\n<p>具体例子：一个部署同时服务流式 TTS 与离线批量声码器，若共用一套 MXFP4 权重与一套校准缩放因子，流式路径的首包延迟因半块填充上升，离线路径的吞吐因块边界错位下降，两条路径都不在最优工作点。分档后，流式路径用按帧对齐的块布局与 MXFP6 关键层，离线路径用按批凑整的块布局与 MXFP4 全层，各自守住自己的约束。这个例子的代价是权重需要两套量化版本，显存占用上升，收益是两条路径都避开各自的失败模式。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-24\">二十四 · 负载不对的边界信号：什么时候该换格式而不是调配方</h3>\n<p>负载配方能修的是块对齐、批形态、逐层位宽这三类问题；修不了的是格式本身与请求形态的结构性冲突。边界信号有三个：请求的帧长分布持续低于块大小，导致缩放因子开销无法摊薄；请求的并发形态是单请求长序列，块内动态范围被长时累积拉大；请求的 SLO 要求首包延迟低于单块反量化的固定开销。出现任一信号时，调配方只能缓解不能消除，应换用非块共享缩放的格式或退回 FP16/BF16 路径。</p>\n<p>机制上，这三个信号都指向同一个量：块缩放的有效载荷比。当每块承载的有效元素数低于某个阈值，缩放因子的读取与反量化开销就超过低精度带来的带宽收益。材料未给出这个阈值的具体数值，但给出了判断方向——块过小则缩放因子开销上升，块过大则动态范围不足。负载配方的职责是在这个区间内找可行点，而不是把区间外的请求硬塞进来。</p>\n<p>代价的最后一项是功耗：MX 格式在张量核心上的低精度矩阵乘降低了对内存带宽与计算单元的压力，但块缩放因子的读取与反量化是额外的常驻开销，在低负载下这部分开销的功耗占比上升。流式形态的请求到达不均匀，空闲期的块加载与唤醒会拉低能效。工程判断是把块加载与请求到达绑定，空闲期不预取缩放因子，用首包延迟的轻微上升换能效。</p>\n<p>具体例子：一个边缘部署的流式编解码器，请求到达间隔大于单块推理时间，若内核持续预取下一块的缩放因子，空闲期带宽被无效占用；若改为到达触发加载，首包延迟增加一次块加载的时间，但空闲功耗下降。这个交换是否划算取决于到达间隔分布与 SLO 的余量，负载配方要在这里给出显式的阈值判断，而不是默认预取。</p>\n<h3 id=\"alg-mx-format-codec-sec-25\">二十五 · 硬件档位：从 MX 原生支持反推部署形态</h3>\n<p>部署配方的第一刀切在硬件档位，而不是模型本身。Blackwell 张量核心原生支持 MX 格式，这意味着 MXFP4/MXFP6/MXINT8 的块缩放矩阵乘不是靠软件模拟，而是由 MMA 指令在 tile 级别直接消费缩放因子与尾数。工程上要问的第一个问题是：目标机型是 B200/B300 单卡，还是 GB200/GB300 NVL72 机柜级？单卡档位下，MX 内核的收益主要体现在单层矩阵乘的吞吐与权重带宽；机柜档位下，收益转移到跨卡激活传输——激活同样按块量化后，NVLink 5 上搬运的是尾数加稀疏缩放因子，而不是 FP16 张量。两种档位的配方差异不在量化格式，而在并行拓扑与 KV 策略的取舍。</p>\n<p>判断档位是否吃满 MX 能力，看一个比值：内核实际吞吐与张量核心 MX 峰值吞吐之比。若内核未对齐张量核心 tile，块缩放因子的加载会打断 MMA 流水，实际吞吐低于预期——这是失败模式里明确点出的。因此硬件档位选型必须与内核实现绑定：CUTLASS 的 MX 路径、TensorRT-LLM 的量化内核、Triton 手写块缩放内核，三者对 tile 对齐的要求不同，部署前要用同一组短帧块负载做对齐验证。</p>\n<div class=\"formula\">$$\\text{有效吞吐} = \\frac{\\text{MMA 周期数}}{\\text{MMA 周期数} + \\text{缩放因子加载周期数}} \\times \\text{MX 峰值}$$</div>\n<p>这个式子说明：块大小 K 越小，缩放因子数量越多，加载周期占比越高。32 元素块是材料给出的锚点，它在缩放开销与动态范围之间取了一个工程上可接受的平衡点；再小则缩放因子开销上升，再大则块内动态范围不足。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-26\">二十六 · 并行拓扑：按层内矩阵乘切分，而不是按层切分</h3>\n<p>MX 格式的并行拓扑有一条硬约束：块缩放因子必须与它所属的 K 元素块在同一设备上，否则反量化要跨卡取缩放因子，通信量翻倍且延迟不可控。因此拓扑按层内矩阵乘切分——把注意力的 QKV 投影、输出投影、声码器卷积的通道维切开，每个 rank 持有完整的块（含缩放因子），而不是按层做流水线切分。层内切分让每个 rank 的权重块自洽，MX 反量化在本地完成，跨卡只同步激活。</p>\n<p>对编解码器注意力，切分维度选头维；对声码器卷积，切分维度选输出通道。两者都要求切分边界落在块边界上：若一个 32 元素块被切到两个 rank，块内最大指数要在两侧各算一次，缩放因子不一致，反量化结果在拼接处出现台阶。工程做法是在切分前把通道数补齐到 K 的整数倍，代价是少量填充计算，收益是块边界与切分边界对齐。</p>\n<p>机柜档位下，激活按块量化后跨卡传输，带宽代价从 FP16 的每元素 16 bit 降到 MXFP4 的每元素 4 bit 加每 32 元素一个缩放因子（约 8 bit），净带宽约为原来的四分之一。这个收益在 NVL72 的 all-to-all 上是实打实的，但前提是 NCCL 的集合通信内核认识块结构，否则缩放因子会被当作独立张量搬运，抵消掉尾数位宽的红利。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-27\">二十七 · 量化方案：逐层选择 MXFP4 / MXFP6 / MXINT8</h3>\n<p>量化方案不是全局一个格式，而是逐层选择。材料给出的三种格式各有分工：MXFP4 尾数最短，权重带宽最省，适合块内分布相对均匀、对高频细节不敏感的层；MXFP6 多两位尾数，留给声码器卷积这类直接决定波形高频段的层；MXINT8 是整数尾数，适合激活动态范围已知、需要确定性数值行为的层。选择依据是逐层的块内指数方差：方差小的层用 MXFP4，方差大的层退到 MXFP6 或 MXINT8。</p>\n<p>声码器卷积与编解码器注意力要分别校准块缩放，这是稳定性技巧的核心。卷积的感受野跨块，若块边界与感受野不对齐，跨块反量化误差会累积，长句推理出现底噪抬升；注意力的块沿头维与序列维展开，误差累积表现为注意力分数的小幅漂移，听感上不如底噪明显但会影响韵律。校准方法是分别统计两类层的块内最大指数分布，对卷积层适当放大块大小或提高尾数位宽，对注意力层保持 32 元素块并用 MXFP6 兜住尾部。</p>\n<table class=\"mini\"><thead><tr><th>层类型</th><th>推荐格式</th><th>块大小</th><th>主要代价</th></tr></thead><tbody><tr><td>编解码器注意力 QKV/输出投影</td><td>MXFP6</td><td>32</td><td>权重带宽中等，尾数够兜注意力尾部</td></tr><tr><td>声码器卷积（高频段）</td><td>MXFP6 或 MXINT8</td><td>32，边界对齐感受野</td><td>块边界误差累积，需校准</td></tr><tr><td>声码器卷积（低频段）</td><td>MXFP4</td><td>32</td><td>带宽最省，高频失真风险低</td></tr><tr><td>激活</td><td>MXFP4/MXFP6</td><td>与权重块对齐</td><td>跨块反量化误差，长句底噪</td></tr></tbody></table>\n<p>逐层调优的代价是预处理复杂度：每层要跑一遍块内指数统计，生成缩放因子表，再与尾数打包存储。这一步在部署流水线里是一次性成本，但格式转换与块缩放的内核实现复杂度是持续成本，材料明确把它列为 MX 的主要代价之一。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-28\">二十八 · KV 策略：KV 与激活同样按块量化</h3>\n<p>KV 策略在 MX 部署里不是独立选项，而是与激活量化共用一套块结构。KV cache 按块量化后，每 32 个元素共享一个缩放指数，解码阶段的 KV 读取带宽随之下降。对编解码器 LM 的流式解码，KV 增长是长句推理的主要显存压力，块量化把每 token 的 KV 占用压到低比特尾数加缩放因子，显存代价从 FP16 的线性增长变成低位宽线性增长。</p>\n<p>但 KV 块量化有一个陷阱：块边界与序列位置不对齐时，跨块反量化误差在长句上累积，表现为底噪抬升。工程做法是让 KV 的块沿头维切分，而不是沿序列维切分——每个头的 KV 向量独立成块，块内元素同分布，缩放因子稳定。序列维只决定块的数量，不决定块的组成。这样解码时新 token 追加到序列尾，只影响新块的缩放因子，不扰动已有块。</p>\n<p>KV 量化的延迟代价出现在首包：预填阶段要为新写入的 KV 计算块内最大指数并生成缩放因子，这一步与预填矩阵乘串行。若预填块大小与张量核心 tile 对齐，缩放因子生成可以融进预填内核，首包延迟不额外增加；若不对齐，缩放因子生成成为独立 kernel，首包延迟上升。SLO 以首包延迟与实时率为约束，材料未给出具体数值，但配方上应把 KV 块大小与预填 tile 绑定。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-29\">二十九 · 调度参数：批大小按块内元素与 tile 对齐</h3>\n<p>调度参数的第一项是批大小。负载配方写明批大小按块内元素与张量核心 tile 对齐，这意味着批不是随意取的整数，而是要让每个 batch 的激活块数落在 tile 的整数倍上。若批大小与 tile 错位，MX 内核的块缩放加载会跨 tile 边界，MMA 流水被打断，吞吐下降。对齐的批大小让每个 tile 消费整数个块，缩放因子加载与 MMA 交替进行，流水不空转。</p>\n<p>第二项是连续批处理的块粒度。流式 TTS 的请求是短帧块，不同请求的帧长不同，连续批处理要在帧块级别做拼批，而不是请求级别。拼批时每个请求的激活块独立保留缩放因子，拼批后的矩阵乘按块反量化，块间不共享缩放。这样拼批不破坏块结构，代价是拼批后的 tile 利用率受最短帧块限制。</p>\n<p>第三项是实时率约束下的并发上限。MX 量化降低了权重带宽与 KV 显存，并发上限由张量核心的 MX 吞吐与块缩放加载开销共同决定，而不是由显存容量单独决定。容量规划时要把缩放因子加载周期计入每帧的计算预算，否则并发数估高，实时率失守。功耗维度上，低比特尾数减少了数据搬运，张量核心的功耗占比上升，机柜档位下要按 MX 峰值吞吐而非 FP16 峰值做功耗预算。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-30\">三十 · 可复现的配置思路：从负载反推，而不是从格式正推</h3>\n<p>把上述五项串成一条可复现的路径，顺序是负载 → 档位 → 拓扑 → 量化 → 调度，而不是先定 MXFP4 再找场景。第一步用短帧块负载跑基线，记录每层的块内指数方差与高频段失真听感；第二步按档位验证内核 tile 对齐，测有效吞吐与 MX 峰值之比；第三步按层内矩阵乘切分拓扑，检查切分边界是否落在块边界；第四步逐层选格式，卷积层优先 MXFP6 兜高频，注意力层按方差在 MXFP4 与 MXFP6 间选；第五步把批大小、拼批粒度、并发上限与 tile 对齐绑定，用实时率与首包延迟做验收。</p>\n<p>验收的失败信号有三个，对应材料给出的失败模式：声码器高频段齿音与气声发闷，说明尾数位宽过小或卷积块未对齐感受野；实际吞吐低于预期，说明内核未对齐张量核心 tile；长句推理底噪抬升，说明激活或 KV 的块边界与感受野/序列位置错位。三个信号分别指向量化方案、内核实现、KV 策略，排查顺序与配置顺序相反——先查调度与 KV，再查内核，最后才动量化格式，因为格式改动会牵动整条预处理流水线。</p>\n<p>这条路径的可复现性来自每一步都有可观测的中间量：块内指数方差、有效吞吐比、切分边界对齐检查、逐层失真听感、实时率与首包延迟。材料未给出具体批大小与 SLO 数值，因此配方以相对量验收——有效吞吐比、带宽下降比例、底噪是否可闻——而不是绝对数字。部署配方的工程判断落在最后一步：当 MX 内核的缩放因子加载开销超过尾数位宽带来的带宽节省时，退回到更大的块或更高的尾数位宽，而不是继续压格式。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-31\">三十一 · 边界条件：块缩放何时失效、代价落在哪一层</h3>\n<p>这套配方的有效性由块内权重分布的均匀性决定，而失效点几乎总在声码器的高频段。MX 的块共享指数把动态范围压缩到 $K$ 个元素内，若某块恰好跨越卷积核中幅度悬殊的两组权重，$s=2^{e_{\\max}}$ 会被最大值主导，小幅度元素在低比特尾数下被压到零或只剩一两个量化级——听感上就是齿音发虚、气声发闷。判断准则可写成块内动态范围比：当 $\\max_j|x_j|/\\min_j|x_j|$ 超过尾数可表达的级数（MXFP4 尾数仅数个有效位），该块即进入失真区。工程上不是逐块检查，而是按层统计这一比值的分布，把超限比例高的层从 MXFP4 升到 MXFP6 或 MXINT8，其余层保持低比特——逐层选择量化方案的意义正在于此，而非全局统一档位。</p>\n<p>第二个失效条件是块边界与卷积感受野不对齐。激活按块量化时，若块划分与卷积的滑动窗口错位，跨块反量化误差会在长句推理中逐帧累积，表现为底噪抬升而非突发失真，这类问题在短帧测试中不易暴露，必须用长句流式回放才能观测。缓解手段是让激活块沿通道维对齐到卷积 tile，并在声码器与编解码器注意力之间分别校准缩放因子，不共用一套统计量。</p>\n<p>系统代价集中在三处。其一是缩放因子开销：块越小，每 $K$ 个元素附带的指数占比越高，等效带宽从 $b$ 位/元素升至 $b + e/K$ 位，$K=32$ 时指数摊薄尚可接受，$K$ 降到 16 以下则存储与加载开销明显上升。其二是内核实现：MX 格式转换与块反量化若未对齐张量核心 tile，实际吞吐会低于理论值，这部分成本落在预处理与自定义内核上，而非矩阵乘本身。其三是调度侧，流式 TTS 的 SLO 由首包延迟与实时率双约束，批大小需按块内元素数与 tile 对齐，批过大拉高首包延迟，批过小则张量核心利用率不足——材料未给出具体数值，需按目标硬件实测确定拐点。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>观测手段</th><th>处置</th></tr></thead><tbody><tr><td>高频失真</td><td>块内动态范围超尾数级数</td><td>逐层动态范围比统计</td><td>该层升 MXFP6/MXINT8</td></tr><tr><td>底噪抬升</td><td>激活块与卷积 tile 错位</td><td>长句流式回放</td><td>通道维对齐、分层校准</td></tr><tr><td>吞吐不达预期</td><td>内核未对齐 tile</td><td>内核级 profiling</td><td>重写块加载路径</td></tr></tbody></table>\n<h3 id=\"alg-mx-format-codec-sec-32\">三十二 · 带宽账本：MX 把权重搬运压到哪一层</h3>\n<p>推理系统里最先崩的通常不是算力，而是字节。声码器与编解码器的解码路径是典型的“权重带宽敏感、算术强度偏低”负载：每层矩阵乘的 FLOPs 与权重字节数之比往往只有个位数到十几，张量核心的峰值算力根本喂不满。把权重从 FP16 换成 MXFP4，单元素从 16 bit 降到 4 bit 尾数加共享指数，块内 32 个元素共享一个 8 bit 缩放因子，等效位宽约为 4 + 8/32 = 4.25 bit，权重流量降到 FP16 的约 26.6%。这个比例直接映射到解码步的权重加载时间上：在带宽受限的层里，步延迟近似正比于权重字节数，因此 MXFP4 把这类层的下限压到原来的四分之一量级。</p>\n<p>但账本不能只算尾数。块缩放因子本身要占带宽，且它的访问模式与尾数不同——尾数是连续流式读取，缩放因子是每 32 元素一次的稀疏索引。若内核把缩放因子单独放在一块显存里，每次 tile 加载都要额外发起一次小事务，事务开销在 L2 与 HBM 之间被放大。工程上的做法是把缩放因子与尾数交错打包成同一 cacheline 友好的布局，让一次 128B 事务同时带回若干块的尾数与对应指数，避免缩放因子成为独立的小颗粒随机访问。这一步不做，MX 的理论带宽收益会在实际内核里被事务开销吃掉大半。</p>\n<p>具体例子：声码器上采样阶段的卷积层，权重张量按输出通道切分，每通道一组 32 元素块。若块沿通道内维连续排列，则一个张量核心 tile 覆盖的块数正好是 tile 宽度除以 32；此时缩放因子的加载次数等于 tile 数，与尾数加载同量级，不会形成额外瓶颈。反之若块跨通道边界切分，同一 tile 内会命中多个不连续的缩放因子，加载次数翻倍，吞吐下降。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-33\">三十三 · 显存与 KV：块量化的驻留成本</h3>\n<p>权重驻留是静态的，KV 与激活驻留是动态的，后者才是规模上去后先崩的地方。编解码器注意力的 KV 若按块量化，显存占用由三部分构成：尾数、块缩放因子、以及为反量化准备的对齐填充。以块大小 K=32、MXINT8 为例，每 32 个 KV 元素占 32 字节尾数加 1 字节指数，另有对齐填充；相比 FP16 的 64 字节，名义压缩比约 2 倍，但填充与元数据会把实际压缩比拉低。块越小，元数据占比越高：K=16 时指数开销翻倍，K=64 时动态范围不足的风险上升。这就是块大小作为折中参数的显存侧含义。</p>\n<div class=\"formula\">$$B_{\\text{kv}} \\approx N_{\\text{elem}}\\left(b_m + \\frac{b_s}{K}\\right) + B_{\\text{pad}}$$</div>\n<p>其中 $b_m$ 为尾数位宽，$b_s$ 为缩放因子位宽，$B_{\\text{pad}}$ 为对齐填充。这个式子说明：当 $K$ 缩小一半，元数据项翻倍；当尾数从 8 bit 降到 4 bit，主项减半但元数据项不变，因此低比特下元数据的相对权重显著上升。规模上去后，KV 的增长是线性的、随并发与上下文长度双重放大，而权重是常数——所以显存先崩的一定是 KV 侧，不是权重侧。</p>\n<p>代价还体现在反量化的临时缓冲上。块内反量化需要在寄存器或共享内存里把尾数展开成 FP16/BF16 再做矩阵乘，若 tile 形状与块边界不对齐，临时缓冲会出现跨块拼接，共享内存占用上升，occupancy 下降。工程判断是：让 tile 的内维是 K 的整数倍，把反量化限制在寄存器内完成，避免共享内存往返。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-34\">三十四 · 通信：分离式部署下的量化收益与元数据开销</h3>\n<p>预填与解码分离部署时，KV 要在节点间搬运，通信量直接决定尾延迟。MX 量化在这里的收益是双面的：尾数与指数一起传，字节数下降，但接收端要做反量化，反量化本身是计算而非通信，若接收端张量核心正忙，反量化会排队，把通信节省的时间还回去一部分。更麻烦的是块边界与传输分片边界不对齐：一次 NCCL 传输按固定字节切分，若切分点落在块中间，接收端需要跨分片拼接缩放因子，产生额外的同步点。</p>\n<p>具体机制：发送端按块打包，保证每个传输分片的起始偏移是 K 的整数倍，接收端即可独立反量化每个分片，无需等待相邻分片。这要求分片大小是 K 与尾数字节数的公倍数。若做不到，接收端必须缓存半个块，尾延迟出现抖动。规模上去后，节点数增加、分片变小，对齐约束更难满足，这是 MX 在分离式部署里最先暴露的系统性问题。</p>\n<p>功耗侧：通信字节下降带来 SerDes 与 NIC 的功耗下降，但反量化的额外计算把功耗转移到 SM 侧。净效应取决于链路功耗与计算功耗的比例；在 NVLink 域内，链路功耗占比低，量化收益主要体现在延迟而非功耗；跨节点时链路功耗占比上升，量化收益更明显。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-35\">三十五 · 尾延迟：块边界误差累积与实时率约束</h3>\n<p>流式 TTS 的 SLO 是首包延迟与实时率，两者都对尾延迟敏感。MX 的尾延迟来源不是平均吞吐，而是块边界处的量化误差累积。激活按块量化时，若块边界与卷积感受野不对齐，跨块反量化会把相邻块的误差带入同一输出点，长句推理时误差沿时间轴累积，表现为底噪抬升。这不是精度问题而是系统问题：误差累积让某些帧的反量化路径变长（需要更多修正），尾延迟分布出现长尾。</p>\n<p>伪代码思路：对卷积层，按感受野对齐块边界，即块起点取感受野起点的整数倍，使每个输出点只依赖完整块内的激活；对注意力层，按 head 维切块，使 QK^T 的内积不跨块。这样反量化误差被限制在块内，不随序列长度累积。代价是块大小受感受野与 head 维约束，不能任意取小，压缩比的上限被结构锁死。</p>\n<p>实时率约束下，解码步的预算被切成固定份额，任何一步的超时都会挤占后续步。MX 内核若未对齐张量核心 tile，实际吞吐低于预期，单步超时概率上升，尾延迟直接恶化。工程判断：先保证 tile 对齐与块边界对齐，再谈尾数位宽的进一步压缩；顺序反了，压缩收益会被尾延迟吃掉。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-36\">三十六 · 规模上去以后哪里先崩</h3>\n<p>按崩溃顺序排列：第一是 KV 显存，随并发与上下文线性增长，块量化的元数据开销在低比特下相对权重上升，压缩比不及预期；第二是尾延迟，块边界误差累积与内核 tile 未对齐共同作用，长句与高并发下长尾变厚；第三是通信对齐约束，分离式部署节点数增加后分片变小，块边界与传输边界对齐难度上升；第四才是权重带宽，它是常数项，规模上去后反而不再是瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>资源</th><th>随规模的增长方式</th><th>MX 的作用</th><th>先崩条件</th></tr></thead><tbody><tr><td>KV 显存</td><td>线性于并发×上下文</td><td>尾数减半，元数据占比上升</td><td>低比特+小块，压缩比被元数据稀释</td></tr><tr><td>尾延迟</td><td>随序列长度与并发非线性</td><td>块内误差隔离可抑制累积</td><td>块边界与感受野/tile 不对齐</td></tr><tr><td>通信</td><td>随节点数与分片数上升</td><td>字节下降，反量化转移计算</td><td>分片边界落在块中间</td></tr><tr><td>权重带宽</td><td>常数</td><td>等效位宽降至约 4.25 bit</td><td>通常不是首个瓶颈</td></tr></tbody></table>\n<p>这张表的工程含义是：MX 的收益在权重带宽上是确定的，但在 KV 与尾延迟上是条件性的。规模上去后，系统瓶颈从“搬权重”转向“搬 KV 与守尾延迟”，此时块大小与尾数位宽的选择要按 KV 侧与延迟侧重新校准，而不是沿用权重侧的调优结果。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-37\">三十七 · 逐层校准作为系统调优手段</h3>\n<p>逐层选择 MXFP4/MXFP6/MXINT8 不是精度偏好，而是系统调优：声码器高频段对尾数位宽敏感，过小尾数引入齿音与气声发闷，这些层用 MXFP6 或 MXINT8 换取听感；编解码器注意力层对块边界敏感，用较大块与对齐切分换取尾延迟稳定；带宽受限的上采样卷积层用 MXFP4 压流量。三者的组合决定了整机的带宽、显存与尾延迟分布。</p>\n<p>校准的代价是预处理与内核实现复杂度：每层一套块大小与位宽意味着多套内核变体，编译与调优成本上升；若内核未对齐张量核心 tile，实际吞吐低于预期。工程判断是先把内核变体收敛到少数几种 tile 形状，再在形状内做逐层位宽选择，避免变体爆炸。规模上去后，变体管理与内核选择逻辑本身会成为部署复杂度的来源，这与块大小过小导致缩放因子开销上升是同一类问题——元数据与配置的组合爆炸，最终以吞吐与尾延迟的形式体现出来。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-38\">三十八 · 块缩放格式在规模上的崩点：缩放因子带宽、块边界与尾延迟</h3>\n<p>MX 格式的系统代价首先不在算力，而在缩放因子的搬运。每 32 个元素共享一个指数，意味着每 32 个低比特尾数就附带一个额外字段；当尾数压到 MXFP4，缩放因子在存储与带宽中的占比迅速抬升，权重与激活的有效位宽不再是名义上的 4 位。设块大小为 $K$、尾数位宽 $b$、缩放因子位宽 $e$，则有效位宽为</p>\n<div class=\"formula\">$$b_{\\text{eff}} = b + \\frac{e}{K}$$</div>\n<p>K 取 32、e 取 8 时，MXFP4 的实际搬运量接近 4.25 位/元素，MXFP6 接近 6.25 位/元素。对声码器这类以卷积为主、权重总量不大的层，缩放因子带来的额外访存与反量化指令开销会吃掉低精度收益；对编解码器注意力层，激活按块量化后每层都要在块内做一次反量化再进张量核心，若内核未与张量核心 tile 对齐，实际吞吐低于预期，这是规模上去后最先暴露的崩点——不是算力不够，而是缩放因子与尾数的加载节奏打乱了 MMA 流水。</p>\n<p>第二个崩点是块边界与感受野错位。声码器卷积的跨块反量化误差会在块边界累积，长句推理表现为底噪抬升；编解码器注意力若按块量化 K/V，块边界与注意力窗口不对齐时，跨块误差随序列长度线性叠加。尾延迟在这里比平均延迟更敏感：流式 TTS 的短帧块本身元素数少，块内最大指数统计的样本不足，缩放因子抖动直接反映为首包延迟的方差异常。工程判断是块大小不能一刀切，卷积层宜用较大块以摊薄缩放开销，注意力层宜按头维度对齐块边界，并对声码器高频段单独校准尾数位宽，否则齿音与气声发闷的失真会在规模放大后被听感放大。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>代价形态</th></tr></thead><tbody><tr><td>层数/序列变长</td><td>块边界误差累积</td><td>底噪抬升、尾延迟方差</td></tr><tr><td>批内块数上升</td><td>缩放因子访存</td><td>有效带宽、MMA 流水断流</td></tr><tr><td>尾数位宽过小</td><td>高频段重建</td><td>音质失真、返工重调</td></tr></tbody></table>\n<h3 id=\"alg-mx-format-codec-sec-39\">三十九 · 精度失效的三种可观测形态</h3>\n<p>MX 编解码器推理的精度失败不是单一现象，而是沿数据流分层显现。第一层是块内尾数截断：当某块（K=32）内元素动态范围跨度过大，共享指数 $s=2^{e_{\\max}}$ 被最大元素“拉高”，小块内小幅值元素的有效尾数位被压缩，反量化后成为量化噪声。第二层是块边界与卷积感受野错位：声码器卷积核跨越相邻块时，两侧各自用不同缩放因子反量化，跨块累加产生不连续的阶跃，长句合成中表现为底噪抬升。第三层是逐层误差累积：编解码器注意力层与声码器卷积层若共用同一套块大小与位宽策略而未分别校准，误差在层间放大。</p>\n<p>诊断上要把“听感失真”翻译成可监控的量。对每一层输出维护块级统计：块内最大值 $e_{\\max}$ 的分布直方图、块内尾数饱和率（尾数达到可表示上限的比例）、反量化前后逐元素相对误差。工程判据是：若某层饱和率在正常负载下持续高于基线，说明该层权重分布与所选位宽不匹配，应下调块大小或升位宽（MXFP4→MXFP6）。齿音与气声发闷对应高频段信噪比下降，可在声码器输出做短时频谱对比，定位到具体上采样层。</p>\n<p>代价落在预处理与内核两侧：逐层调优意味着离线阶段要对每层做块统计与位宽搜索，转换管线复杂度上升；推理时若块缩放因子未与张量核心 tile 对齐，内核会插入额外的重排与掩码，吞吐低于预期。一个具体例子：声码器某卷积层权重块内同时含大幅值基频分量与小幅值谐波分量，MXFP4 下谐波尾数只剩极少数有效位，反量化后谐波被噪声淹没——此时把该层单独切到 MXFP6，其余层维持 MXFP4，即可在不整体升位宽的前提下恢复高频细节。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-40\">四十 · OOM 的来源不是权重而是激活与块元数据</h3>\n<p>MX 格式本身压缩了权重带宽，但显存压力会从别处冒出来。其一是激活按块量化：流式 TTS 的短帧块在批内堆叠时，激活张量的块缩放因子随块数线性增长，块越小元数据占比越高——K=32 时每 32 个元素附带一个指数，元数据开销不可忽略。其二是 KV 与激活同时按块量化后，反量化缓冲区需要 FP16/BF16 落地，若内核采用“先整块反量化再乘”的朴素实现，峰值显存等于低比特存储加全精度缓冲两份。其三是连续批处理下请求长短不一，最长请求的激活块决定批内峰值。</p>\n<div class=\"formula\">$$\\text{峰值显存} \\approx \\underbrace{N_w \\cdot (b_m + b_s/K)}_{\\text{权重低比特+缩放}} + \\underbrace{A \\cdot (b_m + b_s/K)}_{\\text{激活}} + \\underbrace{A \\cdot b_{fp}}_{\\text{反量化缓冲}}$$</div>\n<p>其中 $b_m$ 为尾数位宽、$b_s$ 为缩放因子位宽、$b_{fp}$ 为回写精度位宽。诊断路径是分项打点：权重常驻、激活峰值、反量化缓冲峰值、块元数据四类分开统计，避免把 OOM 笼统归因于“模型太大”。缓解手段按代价排序：优先让内核做块内融合反量化（消除全精度缓冲），其次对激活采用更大块（K 增大降低元数据占比，但牺牲动态范围），最后才是降批或分块流式处理——后者直接抬高首包延迟，属于 SLO 敏感操作，应放在回滚预案里而非默认路径。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-41\">四十一 · 批抖动与路由不均的耦合</h3>\n<p>流式编解码器推理的批由短帧块组成，批大小按块内元素与张量核心 tile 对齐。抖动来自两个方向：请求到达间隔不均导致批内块数在相邻迭代间跳变；不同请求的帧块在层内矩阵乘中走不同 tile，若某请求的块尺寸与 tile 不整除，该请求的 kernel 走慢路径，拖累整批。路由不均则出现在并行拓扑按层内矩阵乘切分时：某些层的 MX 内核实现成熟、吞吐高，另一些层（如声码器特定卷积）内核未对齐 tile，成为批内长尾。</p>\n<p>监控上不要只看整批吞吐，要按请求维度记录每迭代的块数、每请求的 kernel 走快/慢路径标记、以及每层的实际占用时间。判据是：若批内最慢请求的完成时间与批均值之比持续偏大，且慢请求集中在特定层，则为路由不均而非负载不均。调度侧的对策是把块尺寸对齐到 tile 边界（填充而非裁剪，避免改变语义），并对慢路径层单独设并发上限，防止其拖垮整批。代价是填充引入无效计算，吞吐略降但尾延迟收敛；这是用少量吞吐换 SLO 稳定性的典型取舍。</p>\n<p>具体例子：某批内同时存在 32 元素整块的请求与尾块不足 32 的请求，后者触发掩码路径，其声码器卷积层耗时显著高于前者，整批完成时间被拉长。把尾块填充到整块并对该层限流后，批均值时间上升但 P99 尾延迟下降——这正是批抖动诊断要盯的指标对。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-42\">四十二 · 尾延迟尖刺的定位顺序</h3>\n<p>尾延迟尖刺在 MX 推理里通常不是算力问题，而是格式转换与内核切换的瞬时开销。定位顺序应为：先看是否发生位宽切换（逐层选择 MXFP4/MXFP6/MXINT8 时，若运行时按输入动态选位宽，切换点会触发内核重编译或重排）；再看是否发生块大小变更导致的缓冲区重分配；最后看是否因激活块边界与卷积感受野错位触发额外的跨块同步。三者都会在时间线上留下可辨识的尖刺形态：切换型尖刺呈周期性、与请求内容相关；重分配型尖刺与批大小跳变同步；同步型尖刺集中在长句请求。</p>\n<p>监控手段是给每次内核调用打上格式标签（位宽、块大小、是否快路径），按标签聚合延迟分位数。若某标签的 P99 显著高于同层其他标签，即为尖刺源。回滚策略按粒度分级：最轻的是把该层固定回单一 MXFP6（消除切换），其次是回退到块内融合反量化的旧内核，最重的是该层临时走 FP16/BF16 路径——后者带宽代价明显，仅作为止血手段并需同步上调容量余量。回滚必须可逐层执行，因为尖刺往往只集中在声码器少数卷积层，全局回滚会白白牺牲其余层的低精度收益。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-43\">四十三 · 监控指标与回滚闸门</h3>\n<p>监控面要覆盖精度、资源、调度三层，且每层都要有可自动触发的闸门。精度层：块饱和率、反量化相对误差、声码器输出高频段信噪比（离线抽样比对）、长句底噪趋势。资源层：权重/激活/缓冲/元数据四类显存分项、块缩放因子加载带宽占比、张量核心 MX 指令占用率。调度层：批内块数方差、慢路径请求占比、按格式标签的 P99 延迟。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主监控量</th><th>闸门动作</th><th>代价</th></tr></thead><tbody><tr><td>高频失真</td><td>块饱和率、高频信噪比</td><td>该层升位宽至 MXFP6</td><td>带宽与算力上升</td></tr><tr><td>OOM</td><td>反量化缓冲峰值</td><td>切融合反量化内核</td><td>内核实现复杂度</td></tr><tr><td>批抖动</td><td>批内块数方差</td><td>尾块填充对齐 tile</td><td>无效计算、吞吐略降</td></tr><tr><td>路由不均</td><td>慢路径请求占比</td><td>慢层单独限流</td><td>该层并发下降</td></tr><tr><td>尾延迟尖刺</td><td>格式标签 P99</td><td>该层固定位宽/回退内核</td><td>失去动态选位宽收益</td></tr></tbody></table>\n<p>闸门设计的关键是“逐层可回滚”与“回滚不改变语义”。位宽切换与内核回退都不改变数值语义的上界，只改变精度与速度；而块大小变更会改变量化网格，属于语义敏感操作，必须走离线重校准而非在线热切。工程判断是：把在线回滚限定在位宽与内核两个维度，块大小与逐层校准策略只在发布前定版——这样尾延迟尖刺的止血路径最短，也不会引入新的精度漂移。</p>\n<p>最后落在具体机制上：声码器卷积层与编解码器注意力层应各自持有独立的块缩放校准表与位宽选择，监控按层聚合、闸门按层触发；当某层饱和率越过阈值时，只把该层的缩放因子表切换到位宽更高的版本，其余层与批调度保持不变。这条路径把“精度问题、OOM、批抖动、路由不均、尾延迟尖刺”五类失败收敛到同一套逐层标签体系下，使诊断与回滚共享同一份元数据，而不必为每种失败模式另建一套观测管线。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-44\">四十四 · 块缩放编解码器的失效链：从高频失真到尾延迟尖刺</h3>\n<p>MX 格式在音频模型上的失效往往不是\"精度掉了\"这么笼统，而是沿着一条可定位的链条传播。最典型的一条是<strong>尾数位宽与块大小的错配</strong>：当某层声码器卷积被统一压到 MXFP4、块大小取 32 元素时，块内最大指数由少数大幅值权重决定，其余小幅值元素只剩 1 位有效尾数，反量化后相当于在该块内引入了与信号幅度相关的量化台阶。这类误差在低频段被掩蔽，但在齿音与气声所在的高频段直接表现为发闷、毛刺。诊断上不能只看整句 PESQ 类指标，要按频带切片比对 MX 输出与 FP16 参考的频谱包络，定位是哪一层、哪个块的尾数不足。工程代价是校准成本：逐层选择 MXFP4/MXFP6/MXINT8 意味着每层都要跑一遍参考对比，预处理流水线多出一轮离线扫描。</p>\n<p>第二条失效链是<strong>激活块边界与卷积感受野不对齐</strong>。权重按 32 元素分块是静态的，但激活按块量化时，块边界落在卷积核跨步位置上，相邻块的缩放因子不同，反量化误差在跨块累加中不能抵消。公式上，若第 <em>b</em> 块与第 <em>b+1</em> 块的缩放因子分别为 $s_b$、$s_{b+1}$，则跨块卷积输出为 $\\sum_i s_b m_i w_i + \\sum_j s_{b+1} m_j w_j$，两个缩放因子的比值直接放大了边界处的舍入残差。长句流式推理中这类残差逐帧累积，表现为底噪抬升而非单帧爆音——监控上要盯的是<strong>静音段的噪声底</strong>随帧序号漂移，而不是峰值信噪比。代价落在内核实现：块缩放因子需与张量核心 tile 对齐加载，若 tile 边界与 32 元素块不整除，内核要做额外重排，实际吞吐低于理论值。</p>\n<p>第三条是<strong>批抖动与路由不均引发的尾延迟尖刺</strong>。流式 TTS 的请求是短帧块，批大小按块内元素与张量核心 tile 对齐；一旦某个请求的帧块因文本长度突变而尺寸跳变，连续批处理中的批组成被打破，tile 利用率下降，该批的实时率约束被击穿。更隐蔽的是路由不均：编解码器注意力层与声码器卷积层的 MX 内核开销不同，若调度器按请求数而非按层耗时均衡，少数解码步会集中落到慢层上，形成 p99 尖刺。监控应采集<strong>每层每批的块缩放加载耗时</strong>与批内 tile 占用率，用 $\\text{尾延迟} = \\max_{\\text{batch}} (\\text{帧数} \\times \\text{每帧层耗时})$ 作为容量规划的上界估计，而不是用平均吞吐反推。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>齿音发闷、高频毛刺</td><td>按频带比对 MX 与 FP16 参考</td><td>该层尾数升到 MXFP6/MXINT8</td></tr><tr><td>长句底噪抬升</td><td>静音段噪声底随帧漂移</td><td>激活块与感受野对齐或加大块</td></tr><tr><td>吞吐低于预期</td><td>块缩放加载与 tile 占用率</td><td>块大小对齐张量核心 tile</td></tr><tr><td>p99 尖刺</td><td>按层耗时与批组成追踪</td><td>按层耗时而非请求数均衡</td></tr></tbody></table>\n<p>回滚策略必须是<strong>逐层粒度而非全局粒度</strong>：把某一层从 MXFP4 退回 MXFP6 只影响该层带宽与算力，整模型退回 FP16 则丢掉全部 MX 收益。工程判断是：为每层保留一份尾数位宽与块大小的配置快照，配合频带级与噪声底级两条监控阈值触发单层回滚；OOM 风险主要来自块缩放因子的额外存储与激活量化缓冲，按块数而非按元素数估算显存增量，块越小因子开销越大，这也是块大小不能一味取小的系统原因。</p>\n<h3 id=\"alg-mx-format-codec-sec-45\">四十五 · 同族谱系：MX 在低精度格式里的坐标</h3>\n<p>把 MX 放回低精度格式的谱系里，选型问题才成立。同一族至少有四个成员：全局 INT8（含通道级缩放的 SmoothQuant 类做法）、FP8（E4M3/E5M2）、NVFP4（16 元素块共享 FP8 缩放因子），以及 MX（32 元素块共享 2 的幂指数缩放）。它们的差别不在“位宽”这一个维度上，而在缩放因子的粒度、缩放因子的数值类型、以及块内元素是否共享指数三件事上。全局 INT8 只有一个（或每通道一个）缩放因子，动态范围靠校准吸收；FP8 用浮点指数给每个元素独立的动态范围，但尾数只有 3 位或 2 位；NVFP4 把缩放因子缩到 16 元素一块，且缩放因子本身是 FP8，能表达非 2 的幂；MX 把块拉到 32 元素，缩放因子强制为 2 的幂，于是反量化退化成一次指数加法与移位。</p>\n<p>这个结构性差异直接决定内核代价。MX 的 2 的幂缩放意味着块内反量化可以写成 $x_i = m_i \\ll (e_{\\max} - e_{\\text{base}})$ 这样的整数移位，不引入乘法，也不引入缩放因子的额外精度损失；代价是缩放因子只能落在 2 的幂格点上，块内最大值与次大值差距大时，小值元素的有效位数被浪费。NVFP4 的 FP8 缩放因子能贴合块内最大值，但每次反量化要一次真正的浮点乘。对声码器这种卷积层权重分布偏重尾、编解码器注意力层权重分布偏均匀的混合负载，这个差别会体现在内核实现复杂度而非理论算力上。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>缩放粒度</th><th>缩放数值类型</th><th>反量化代价</th><th>典型失效面</th></tr></thead><tbody><tr><td>全局 INT8</td><td>张量/通道</td><td>FP32</td><td>一次乘</td><td>离群通道整层掉精度</td></tr><tr><td>FP8 E4M3</td><td>逐元素</td><td>浮点指数</td><td>无（原生格式）</td><td>尾数不足，小值被吞</td></tr><tr><td>NVFP4</td><td>16 元素</td><td>FP8</td><td>一次乘</td><td>缩放因子自身量化误差</td></tr><tr><td>MX</td><td>32 元素</td><td>2 的幂指数</td><td>整数移位</td><td>块内动态范围不足</td></tr></tbody></table>\n\n<h3 id=\"alg-mx-format-codec-sec-46\">四十六 · 选型的第一判据：块内分布均匀度</h3>\n<p>MX 的适用条件可以压缩成一个可测量的量：块内元素的指数跨度。设块内最大指数为 $e_{\\max}$、最小非零指数为 $e_{\\min}$，尾数位宽为 $b$，则块内可表示的最小有效值约为 $2^{e_{\\max}-b}$。若某元素的指数低于 $e_{\\max}-b$，它在该块里被压成零或严重欠采样。于是判据是：块内指数跨度 $e_{\\max}-e_{\\min}$ 应不超过尾数位宽 $b$ 加上一个可容忍的余量。MXFP4 的 $b=3$（含隐含位则有效精度约 4 位），意味着块内指数跨度超过 4 到 5 个二进制数量级时，小块元素基本失效。</p>\n<div class=\"formula\">$$\\text{可用条件：}\\quad e_{\\max}-e_{\\min}\\ \\le\\ b+\\Delta,\\qquad \\Delta\\ \\text{为逐层校准余量}$$</div>\n<p>工程上不必逐块统计，只需在离线校准阶段对每层权重做一次块内指数跨度的直方图。声码器的卷积层若呈现重尾，块内跨度大，选 MXFP6 或 MXINT8 而非 MXFP4；编解码器注意力的 QKV 投影若分布均匀，MXFP4 直接可用。这一步的代价是校准时间与显存：需要把整层权重按 32 元素展开成块视图，对每块求最大指数，再聚合统计。对十亿参数级的声码器，这是一次性的离线开销，不进入推理热路径，但会拉长量化流水线的准备阶段。</p>\n<p>反过来的判据同样重要：若某层块内跨度极小（分布高度均匀），MX 的 2 的幂缩放几乎不损失精度，此时它与全局 INT8 的精度差距可以忽略，选 MX 的唯一理由是张量核心的原生支持带来的吞吐。Blackwell 张量核心原生支持 MX 格式，块缩放矩阵乘在硬件路径上完成，这是 MX 相对“全局 INT8 + 软件反量化”的真实优势所在；若内核未对齐张量核心 tile，这个优势会被吃掉，实际吞吐低于预期。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-47\">四十七 · 选型的第二判据：缩放因子开销占比</h3>\n<p>块大小 $K$ 是一个显式的带宽—精度折中。每个块携带一个缩放因子，若缩放因子用 8 位存储，则每元素摊到的额外位宽是 $8/K$。$K=32$ 时是 0.25 位/元素，$K=16$ 时是 0.5 位/元素。对 MXFP4 而言，$K=32$ 的有效位宽是 4.25 位，$K=16$ 是 4.5 位；位宽上升换来的是块内动态范围收紧、小块元素存活率提高。</p>\n<div class=\"formula\">$$\\text{有效位宽} = b + \\frac{b_s}{K},\\qquad \\text{块内动态范围} \\approx 2^{b}\\ \\text{（受 } e_{\\max} \\text{ 锚定）}$$</div>\n<p>这条判据在流式 TTS 的短帧块负载上尤其敏感。流式推理按帧块推进，激活也要按块量化，若激活块大小与卷积感受野不对齐，跨块反量化误差会累积，长句推理出现底噪抬升。此时把 $K$ 调大能减少块边界数量，但块内动态范围变宽、小块元素被牺牲；把 $K$ 调小能保住小块元素，但缩放因子带宽开销上升，且块边界更密。材料给出的 32 元素是这条曲线的常用工作点，不是普适最优。</p>\n<p>系统代价要按三条线分别记：显存带宽上，MXFP4 相对 FP16 把权重流量压到约四分之一，缩放因子再摊 0.25 位，净收益仍然显著；张量核心吞吐上，MX 格式走原生路径，块缩放矩阵乘的算力利用率取决于 tile 对齐；预处理上，格式转换与块缩放统计是一次性离线成本，但每层都要做，层数多时准备阶段的时间不可忽略。对延迟敏感的流式场景，这笔离线成本必须挡在服务启动之前，不能进入首包路径。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-48\">四十八 · 决策表：按层型与负载形态落位</h3>\n<p>把两条判据交叉，可以得到一张按层型落位的决策表。注意这张表只给适用条件与代价方向，不给具体数值阈值——材料未给出逐层的实测精度与吞吐数字，任何具体阈值都属于编造。</p>\n<table class=\"mini\"><thead><tr><th>层型 / 负载</th><th>块内分布</th><th>推荐格式</th><th>关键代价</th><th>不适用信号</th></tr></thead><tbody><tr><td>声码器卷积（重尾）</td><td>跨度大</td><td>MXFP6 / MXINT8</td><td>位宽上升，带宽收益缩水</td><td>齿音、气声发闷</td></tr><tr><td>编解码器注意力 QKV</td><td>较均匀</td><td>MXFP4</td><td>块边界误差累积</td><td>长句底噪抬升</td></tr><tr><td>注意力输出投影</td><td>中等</td><td>MXFP4 或 NVFP4</td><td>缩放因子精度</td><td>小块元素被吞</td></tr><tr><td>激活（流式短帧）</td><td>随帧波动</td><td>MXINT8 保守起步</td><td>块与感受野对齐</td><td>跨块误差累积</td></tr><tr><td>边缘低比特场景</td><td>受显存约束</td><td>MXFP4 优先</td><td>内核 tile 对齐</td><td>吞吐低于预期</td></tr></tbody></table>\n<p>声码器卷积层是这张表里最需要保守的一格。它的权重动态范围大，FP16 易溢出、INT8 精度损失明显，而 MX 的块共享指数恰好能吸收这种重尾；但 MXFP4 的 3 位尾数对高频段过于苛刻，过小尾数会引入音频高频失真。工程判断是：卷积层从 MXFP6 起步，用离线校准确认高频段无失真后再考虑降到 MXFP4；注意力层可以直接从 MXFP4 起步，因为其分布更均匀、块内跨度小。</p>\n<p>激活量化是另一格需要单独校准的地方。权重可以离线反复调，激活随输入帧变化，块边界与卷积感受野不对齐时误差会跨块传播。做法是对声码器卷积与编解码器注意力分别校准块缩放，而不是全模型共用一套块参数；这增加校准工作量，但避免了块边界处量化误差累积。代价是部署流水线多一个按层型的校准分支，收益是长句推理的底噪可控。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-49\">四十九 · 与 NVFP4 和 FP8 的边界划分</h3>\n<p>MX 与 NVFP4 的分界不在位宽，而在缩放因子的表达能力。NVFP4 的 16 元素块配 FP8 缩放因子，能表达非 2 的幂的块缩放，块内最大值贴合度更高；代价是缩放因子自身要被量化成 FP8，引入一次额外的舍入，且反量化要一次浮点乘。MX 的 2 的幂缩放没有这次舍入，反量化是移位，但块内最大值只能落在 2 的幂格点上，最坏情况下块内最大值被高估最多近一倍，等效损失约一位精度。因此：块内分布贴近 2 的幂格点、或对反量化代价敏感（流式短帧、首包延迟约束紧）时选 MX；块内分布连续、且能容忍一次浮点乘时选 NVFP4。</p>\n<p>与 FP8 的分界更直接。FP8 逐元素带指数，动态范围问题天然不存在，不需要块缩放，也不需要溢出保护；它的短板是尾数只有 3 位（E4M3）或 2 位（E5M2），小值元素的相对精度差。若某层权重分布本身温和、FP8 已能满足音质，就没有理由引入 MX 的块管理开销。MX 的入场理由是“动态范围大到 FP8 的尾数不够、但又不想付 FP16 的带宽”，这正是神经音频编解码器与声码器权重分布的典型画像。</p>\n<p>三条路线的系统代价排序要按场景定：显存带宽上 MXFP4 与 NVFP4 同级，均显著优于 FP16；张量核心路径上 MX 走原生块缩放矩阵乘，NVFP4 也走原生路径但缩放因子处理更复杂；内核实现复杂度上 MX 的移位反量化最简单，NVFP4 次之，全局 INT8 的软件反量化最重。选型时若团队的内核工程能力有限，MX 的简单反量化是实打实的落地优势。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-50\">五十 · 适用条件的硬边界与工程落位</h3>\n<p>MX 的规模上限受两件事约束：张量核心对 MX 格式的支持范围，以及内核实现复杂度。材料未给出具体上限数值，但边界形状是清楚的——块过小则缩放因子开销上升、块过大则动态范围不足，$K=32$ 是这条曲线的常用工作点。当层数极多、每层都要单独校准块参数时，校准与内核分支的维护成本会线性上升，此时应把层型归并成少数几类（卷积类、注意力类、激活类），每类一套块参数，用少量精度换取可维护性。</p>\n<p>工程落位顺序建议是：先做离线块内指数跨度统计，把层分成“均匀”“中等”“重尾”三档；均匀档直接上 MXFP4，中等档在 MXFP4 与 NVFP4 之间按反量化代价选，重尾档上 MXFP6 或 MXINT8；激活单独一档，按块与感受野对齐情况选 MXINT8 保守起步。每档都要过一次听感验证，重点听齿音与气声——这是高频段失真最直接的表征。若内核未对齐张量核心 tile，先修 tile 对齐再谈格式降位，否则吞吐收益会被内核开销吃掉，格式选型失去意义。</p>\n<p>最后一条硬判断：MX 不是“更低位宽”的同义词，它是“块共享 2 的幂缩放”这一特定机制。当某层的瓶颈是尾数精度而非动态范围时，降位宽只会放大失真；当瓶颈是动态范围时，MX 的块共享指数才是对症的解法。把这两类瓶颈分开测量，选型才不会退化成按位宽排序的直觉。</p>\n\n<h3 id=\"alg-mx-format-codec-sec-51\">五十一 · 边界与邻族选型：MX 何时失效、与谁互换</h3>\n<p>MX 的失效条件集中在三处。其一，块内分布不均：若某 32 元素块中仅一两个大幅值元素主导 <span class=\"formula\">$$e_{\\max}$$</span>，共享缩放因子会把其余元素压到极小尾数，MXFP4 的有效位数不足以表达，声码器高频段先崩——听感上是齿音发毛、气声发闷。其二，块边界与卷积感受野错位：激活按块量化时，跨块反量化误差在长句中累积，表现为底噪抬升，这类失真不随批大小改善，只能靠逐层校准块缩放或对卷积层改用通道级缩放规避。其三，内核未对齐张量核心 tile：MX 的缩放因子与尾数需按块加载，若 tile 切分与块边界不重合，反量化开销吃掉低精度收益，实际吞吐低于预期——这是工程代价而非数值代价，必须在 CUTLASS 内核层面先验证。</p>\n<p>与相邻算法对照，选型判据是“动态范围是否块内可控”。全局 INT8（含 SmoothQuant 式通道级缩放）把整层或整通道压到同一尺度，实现简单、内核成熟，适合权重分布平坦的编解码器线性层；一旦某层存在离群通道，全局缩放即失效，此时 MX 的块共享指数是必要升级。FP16 无需溢出保护但带宽翻倍，在声码器卷积这类带宽受限环节，MXFP6 往往比 FP16 更划算；反之，若某层对数值精度极端敏感（如波形合成的最后一层投影），保留 BF16 比强行 MXFP4 更稳。下表给出按层决策的判据。</p>\n<table class=\"mini\"><thead><tr><th>层类型/条件</th><th>首选格式</th><th>失效信号</th><th>系统代价</th></tr></thead><tbody><tr><td>块内分布均匀的注意力投影</td><td>MXFP4</td><td>块内离群值主导 e_max</td><td>缩放因子存储开销随块变小上升</td></tr><tr><td>声码器卷积、带宽受限</td><td>MXFP6</td><td>高频失真、底噪抬升</td><td>尾数位宽增加，带宽高于 MXFP4</td></tr><tr><td>存在通道级离群、内核成熟度优先</td><td>通道级 INT8</td><td>整层精度损失明显</td><td>无块缩放开销，但动态范围不足</td></tr><tr><td>末层投影、精度敏感</td><td>BF16</td><td>—</td><td>带宽与算力代价最高</td></tr></tbody></table>\n<p>决策顺序应为：先按层统计块内最大指数与尾数利用率，块内相对均匀者上 MXFP4；高频段敏感的卷积层退到 MXFP6 并单独校准块缩放；仅当某层离群值集中在固定通道、且内核尚未对齐 MX tile 时，暂用通道级 INT8 过渡。块大小 K 是另一维：K 过小则缩放因子开销与反量化次数上升，K 过大则块内动态范围不足，32 元素是当前与张量核心 tile 对齐的折中起点，但需逐层实测而非全局统一。规模上限不由算法决定，而由 Blackwell 张量核心的 MX 格式支持粒度与内核实现复杂度共同约束，材料未给出具体上限，工程上应以单层吞吐与音质双指标做逐层准入。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 流式投机解码与多 token 预测</td></tr><tr><td>解决什么</td><td>神经音频编解码器与声码器权重动态范围大，FP16 易溢出、INT8 精度损失明显，需在 Blackwell 上以低精度…</td></tr><tr><td>一句话机制</td><td>采用 MX（microscaling）块浮点格式，每 K 个元素共享一个缩放指数，元素用低比特尾数表示，在张量核心上以…</td></tr><tr><td>代价与失效</td><td>块大小与尾数位宽需逐层调优，过小尾数会引入音频高频失真；MX 格式转换与块缩放增加预处理与内核实现复杂度</td></tr><tr><td>后继</td><td>MXFP8 微缩放编解码推理</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-mx-format-codec · 共 8 个片段</p>\n";break;}}})();
